quests[34338] = { id = 34338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abstieg", description = "Was auch immer am Grund dieses Kessels liegt, ist für die Eiserne Horde von großem Nutzen und daher auch für uns von größtem Interesse.\n\nIhr müsst den Boden dieses Kraters für mich untersuchen.\n\nGeht vor, ich bin direkt hinter Euch.", sourceObjective = "Untersucht den Rauchfelskessel.", progress = "<Thisalee schaut Euch kühl an.>", completion = "Das war knapp, {name}. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[34339] = { id = 34339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fressen für die Goren", description = "Goren. Diese Caldera ist voll von ihnen. Ich kann ihren Gestank sogar hier noch riechen.\n\nIch vermute, diese Goren sind mehr als nur primitive Bestien, aber um meine Theorie zu beweisen, benötige ich noch mehr Daten.\n\nWenn Ihr auf Eurer Mission ein oder zwei Goren töten solltet, könntet Ihr dann deren Mägen für mich untersuchen? Ich möchte gerne wissen, was diese seltsamen Kreaturen zu sich nehmen.", sourceObjective = "Sammelt 8 geschwollene Mägen und untersucht ihren Inhalt.", completion = "Meine Güte, was für eine interessante Vielfalt! Anscheinend fressen diese Goren... alles!", sourceObjectiveStatus = "unverified-source-field" }
quests[34340] = { id = 34340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwärmen", description = "Seid gegrüßt, {name}. Ich untersuche jetzt seit einiger Zeit die Dampfgeysire von Gorgrond.\n\nDer Rauchfelskessel ist eine der größten Calderen in diesem Gebiet, doch konnten wir wegen der gefährlichen Kreaturen in dieser Region noch keine geologischen Studien durchführen.\n\nKönnt Ihr die dortige Temperatur für mich ermitteln, wenn Ihr in die Tiefe geht?\n\nDas Ergebnis würde unser Verständnis dieser natürlichen Kavernen immens verbessern.", sourceObjective = "Verwendet Arens Thermometer in der Nähe des Zischenden Geysirs im Rauchfelskessel.", completion = "Meine Güte! Erstaunlich! Diese Caldera ist heißer als heiß! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34341] = { id = 34341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schlagende Herz", description = "Eines ist sicher. Wir besitzen jetzt einen Gegenstand, der für die Eiserne Horde sehr wichtig ist.\n\nWir sollten dieses... Herz von Gorgorek besser sofort in Sicherheit bringen.", sourceObjective = "Bringt das Herz von Gorgorek zu Kriegsmeister Zog in Eurer Garnison.", completion = "Gut. Wir werden das Artefakt hier in Eurer Garnison sicher aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[34344] = { id = 34344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauerer", description = "Das is'n gefährlicher Ort, <Scheff/Scheffin>.\n\nVoll mit großen Monstern un' wilden Riesen.\n\nAlso, wie man bei uns sagt: Was man nicht schlag'n kann, vergiftet man.\n\nWir werden 'ne Menge Gift von den Lauerern da draußen auf den Knirschenden Ebenen brauch'n. Diese Lauerer sind mächtig raffiniert... und mächtig unheimlich. Achtet auf den Boden. Wenn der grollt oder bebt, kann's gefährlich werd'n.\n\nIch bleib hier und bereite 'n Heilmittel vor. Nur für den Fall, dass Ihr Euch versehentlich vergiftet.", sourceObjective = "Sammelt 8 Dosen Lauerergift.", progress = "Habt Ihr etwa Angst vor diesen Lauerern?", completion = "Diese Tausendfüßer jag'n Euch Angst ein, Scheff? Wenn sie Euch mit ihren klitzekleinen Beinchen berühr'n? Ich kann mir nichts vorstell'n, wovon ich schneller Gänsehaut bekomm, außer vielleicht von der Stimme von meiner Schwester. Hihi.", sourceObjectiveStatus = "unverified-source-field" }
quests[34345] = { id = 34345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilpflaster", description = "Wir jagen etwas so Großes und so Wildes, dass wir noch ein anderes Gift brauch'n. Wir werd'n einen ganz schönen Packen Gift brauch'n!\n\nAlso... <Scheff/Scheffin>? Ist Euch ein wenig nach Blumenpflück'n? Wir brauch'n die Blätter von der Frostblüte, die in den Schatten der Felsen und Vorsprünge am Rand der Knirschenden Ebenen wachsen.\n\nPasst auf, wenn Ihr sie pflückt, <Scheff/Scheffin>! Die Gegend ist nich' immer ganz so einsam, wie sie scheint...", sourceObjective = "Sammelt 10 Frostblütenblätter ein.", progress = "Ich würde die Blumen ja selbst pflücken, aber ich bin allergisch. Haha!", completion = "Haha! Ihr habt sie! Ich hoffe, ich habe Euch mit so einer niederen Aufgabe nich' beleidigt. Wir hab'n die Blätter gebraucht... und ich musste eine Wette gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34346] = { id = 34346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostiger Zorn", description = "Die Zorne von Draenor sind anders als die Elementare von Azeroth. Aber lasst Euch nicht täusch'n. Einige sind böse, <Scheff/Scheffin>. Böse.\n\nFür die Falle, die wir aufstell'n, brauch'n wir ein paar ordentliche Frostsplitter. Ihr könnt sie von den Eiszorn'n besorg'n, wenn das für Euch ok is'.\n\nDie zieh'n durch die Knirschenden Ebenen und frier'n alles ein, was sie berühr'n... Ach ja, und die sind böse.\n\nHolt uns ein paar von diesen Frostsplittern, <Scheff/Scheffin>, dann können wir eine echt tödliche Falle zusammenzimmern.", sourceObjective = "Sammelt 3 Frostsplitter ein.", progress = "Ein Schattenjäger kennt sich mit Geistern aus. Wir red'n mit ihnen. Wir handeln mit ihnen. Aber diese Eiszorne, die sind wirklich böse, Scheff.", completion = "Ah, das sind einmal ein paar hübsche Sachen für eine gute Falle. Ihr wisst, wie man einen Schattenjäger mit Stolz erfüllt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34347] = { id = 34347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenwuts Befehle", description = "Leutnant O'rok:\n\nEntsendet einen Elitestoßtrupp zum Rauchfelskessel.\n\nBergt ein hochwertiges Artefakt aus dem Krater und liefert es an meinem Kommandoposten im nördlichen Talador ab.\n\nBegebt Euch mit den verbleibenden Truppen nach Gorgoreks Sturz. Beschützt das Exemplar des uralten Magnaron und bereitet es zur Bergung vor.\n\nSofortiger Handlungsbedarf.\n\n- Klingenwut", sourceObjective = "Bringt Klingenwuts Befehle zu Thisalee Krähe an der Horizontklippe.", completion = "Diese Befehle kommen direkt vom Anführer der Brennenden Klinge!\n\nIch habe von ihr gehört... von der wilden Orcin mit der Klinge, die nach Blut dürstet.\n\nGut, dass Ihr das zu mir gebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34348] = { id = 34348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Richtige Beute", description = "He, <Scheff/Scheffin>. Jetzt wird es Zeit, dass wir die echte Beute jagen. Im Norden ist 'ne Höhle. In der Höhle is' ein richtig fieser Ogron, den man \"Grosh den Mächtigen\" nennt. Dieser Ogron hat ein riesiges Lager mit geplündertem Fell un' Leder, das wir für die Truppen in der Garnison brauch'n.\n\nIch habe aus dem Zeug, das Ihr eingesammelt habt, ein besonderes Gift hergestellt. Das ist ein magisches Gift, und es wird den Ogron ein wenig zurechtstutz'n.\n\nGeht mit diesen Phiolen zur Höhle und seht zu, ob Ihr mit einem Schatz für uns wieder herauskommt.", sourceObjective = "Sucht die Frostbeulenhöhle und tötet Grosh den Mächtigen.", completion = "Also, das nenne ich 'nen netten Fischzug. Wir werd'n die ganzen Leute in der Garnison warmhalten können.\n\nDas scheint eine einfache Aufgabe gewes'n zu sein, aber Ihr seid sie wie ein echter Scheff angegangen. Wenn Ihr 'nen Schattenjäger braucht, bin ich Euch gerne zu Diensten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34351] = { id = 34351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen zusätzliche Pylonen bauen", description = "Wir sind hierher gekommen, um einen Reservepylonen zu besorgen, der die Verteidigung von Auchindoun verstärken soll. Die Angriffe des Schattenrates haben uns hier für Stunden festgenagelt!\n\nDiese Verwundeten müssen zurück zur Zuflucht des Exarchen gebracht werden, trotzem brauchen wir dieses Reservesystem!\n\nBitte sammelt Arkonitkristalle und einen Arkonitpylon aus dem Grab und kommt dann damit so schnell wie möglich zu mir in die Zuflucht!", sourceObjective = "Sammelt 6 Arkonitkristalle und einen Arkonitpylonen aus dem Grab des Lichts.", progress = "Habt Ihr den Arkonitpylonen und die Kristalle?", completion = "Möge das Licht Euch segnen! Wir müssen so lange wie möglich durchhalten, damit Nyami die verbleibenden Energiesplitter ausfindig machen kann. Dieser Pylon wird unsere Seelenpriester etwas entlasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34352] = { id = 34352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtflutverteidiger", description = "<Rexxars Blick ruht auf Euch, während Ihr die toten Goblins untersucht. Es ist offensichtlich, was er sich von Euch erhofft.>", sourceObjective = "Tötet 5 Nachtflutplünderer und 5 Nachtflutingenieure.", sourceObjectiveStatus = "unverified-source-field" }
quests[34353] = { id = 34353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeschreddert", description = "Die Rylaks können sich nicht gegen die Technologie der Eisernen Horde wehren. Ein wahrer Jäger braucht keine Maschinen, um seine Beute einzufangen.\n\nZerstört die Eisenschredder und den Abschaum, der sie steuert. Geisterschwinge wird Euch bei Eurer Aufgabe behilflich sein.", sourceObjective = "Zerstört Nachtflutschredder im Nachtflutnest.", completion = "Ihr erweist Euch als großartiger Jäger, {name}. Doch unsere Arbeit auf dieser Insel ist noch längst nicht abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34354] = { id = 34354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anständiger Tod", description = "Diese Narren haben keine Ehre.\n\nSie scheinen Spaß daran zu haben, diese armen Tiere zu quälen. Wir können ihnen nur noch helfen, indem wir verletzte Rylaks suchen und sie von ihrem Leid erlösen.\n\nNehmt diese Axt und zielt auf die lebenswichtigen Organe, {name}. Diese Rylaks verdienen einen anständigen Tod.", sourceObjective = "Benutzt Rexxars Axt, um verletzte Rylaks im Nachtflutnest zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34355] = { id = 34355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Ratten", description = "Diese Schredder bereiten uns mehr Mühe, als ich erwartet habe.\n\nIch habe durch die Augen der Ratten auf der Insel geschaut. Westlich von hier befinden sich einige unbemannte Schredder.\n\nDie Ratten haben einen unersättlichen Appetit nach diesen Ködern. Werft sie auf die unbemannten Schredder und lasst die Ratten sie von innen heraus zerstören.", sourceObjective = "Benutzt die Ratten, um unbemannte Schredder im Nachtflutnest zu zerstören.", completion = "Wenn diese Schwächlinge weniger Maschinen zur Verfügung haben, werden sie ihre Stellung auf dieser Insel schnell verlieren.\n\nAusgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34359] = { id = 34359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darktide Defender TEST" }
quests[34360] = { id = 34360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SHWAYDER TEST" }
quests[34361] = { id = 34361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: The Bone Crawler" }
quests[34362] = { id = 34362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattentor", description = "In Ordnung, wir werden schnell sein müssen.\n\nIch habe früher schon gesehen, wie Borgal magische Portale errichtet hat, also wird er vielleicht versuchen, durch eins zu entkommen. Wenn er das tut, bleibt uns keine andere Wahl, als ihm zu folgen. Darüber hinaus hat er seinen Leutnant Grubnor immer in seiner Nähe, also kommt vielleicht ein kleines Gerangel auf uns zu.\n\n<Owynn späht in die Höhle.>\n\nHaltet den Kopf unten, da drin geht etwas vor.", sourceObjective = "Besiegt Grubnor Schlachtwanst und folgt Borgal.", completion = "Verdammt, er ist uns entwischt!\n\nDass das Portal von dieser Seite verschlossen zu sein scheint, macht es auch nicht besser. Wir müssen eine Möglichkeit finden, Borgal aufzuspüren, oder wir sitzen vielleicht hier fest, wo immer das auch ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34364] = { id = 34364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde!", description = "Ohne Euch hätte es keiner von uns an die Küste meiner Heimat geschafft. Ihr werdet unsere Streitkräfte hier auf Draenor anführen. Euch soll es obliegen, hier eine Garnison zu gründen.\n\nIch überlasse es Euch, das Banner aufzustellen und dieses Gebiet für Euch zu beanspruchen. Wenn Ihr bereit seid, werde ich Khadgar ein Portal öffnen lassen, um Euch die nötige Verstärkung zu schicken.", sourceObjective = "Platziert das Hordenbanner, um das Land zu beanspruchen.", completion = "Ich wurde Eurem Befehl unterstellt, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[34365] = { id = 34365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für die Rylaks", description = "Diese Goblins haben schreckliche Experimente an den Rylaks durchgeführt. Dieser Narr hat mir verraten, wo sich drei ihrer kostbaren Experimente befinden.\n\nBefreit diese mutierten Rylaks. Vielleicht verhilft die Freiheit diesen gequälten Seelen zu etwas Frieden.", sourceObjective = "Befreit die eingesperrten Rylaks im Nachtflutnest.", completion = "Ausgezeichnete Arbeit, {name}. Ihr erweist Euch als großartiger Verbündeter.", sourceObjectiveStatus = "unverified-source-field" }
quests[34375] = { id = 34375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück an die Arbeit", description = "In Ordnung, Boss. Wir werden etwas Holz brauchen, wenn wir diese Garnison von Anfang an vernünftig errichten wollen.\n\nWenn Ihr ein paar Bäume zum Fällen markiert, übernehmen Eure Peons den Rest.", sourceObjective = "Markiert 6 Bäume.", completion = "Das sollte für den Moment genug Holz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[34377] = { id = 34377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Portal Home" }
quests[34378] = { id = 34378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet Eure Garnison", description = "Zeit für die große Vorstellung! Wir haben die Materialien, wir haben das Muskelschmalz und wir haben noch was Drittes, das mit \"M\" beginnt.\n\nDann wollen wir das Ding mal hochziehen!\n\nIch habe einen ganzen Trupp an Assistenten oben auf der Klippe im Westen.\n\nSie sollten mit dem Aufbau Eures persönlichen Beobachterstands jetzt eigentlich fertig sein. Geht mal rüber! Von dort aus könnt Ihr unseren Fortschritt überwachen.", sourceObjective = "Benutzt den Meistervermesser, um den Bau Eurer Garnison zu verfolgen.", progress = "Ich bin fast so gespannt darauf, das zu bauen, wie Ihr. Ich will es mitbekommen, wenn es auseinanderfällt!", completion = "Gut! Ich glaube, wir haben jetzt alles unter Kontrolle und das fast ganz ohne Explosionen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34379] = { id = 34379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsbau", description = "Durotan möchte, dass wir ihn begleiten, jetzt da Ihr Eure Stellung gesichert habt. Ich hoffe, er nimmt Eure Hilfe an.", sourceObjective = "Reitet auf dem Frostwolfrylak nach Wor'gol.", completion = "Ich hoffe, Euer Land gefällt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[34380] = { id = 34380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Frostwölfe", description = "Mein Bruder hat vorschnell bereits einige aus unserem Klan mitgenommen und einen Überfall auf die Speerspießerfestung gestartet, obwohl wir noch gar nicht bereit sind.\n\nDraka erwartet Euch bei unserem Kriegshorn. Sagt ihr bitte Bescheid, dass es Zeit wird, den Klan zu versammeln!\n\nMit Euch und Euren Streitkräften haben wir vielleicht sogar eine Chance.", sourceObjective = "Bittet Draka, ins Kriegshorn zu blasen.", progress = "Draka wird wissen, was zu tun ist.", completion = "Der Klan ist bereit. Es ist Zeit, zur Speerspießerfestung vorzurücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[34381] = { id = 34381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattentor", description = "Da sin' Oger in der Höhle. Ich kann ihren Gestank riech'n.\n\nHaltet Eure Waffe bereit, wir müss'n schnell sein und die Oger niedermach'n, bevor sie das Mojo benutzen.\n\n<Bwu'ja wirft einen Blick in die Höhle.>\n\nPasst auf Euch auf, Mann, da drin geht irgendetwas vor.", sourceObjective = "Besiegt Grubnor Schlachtwanst und folgt Borgal.", completion = "Der Oger is' uns entwischt!\n\n<Bwu'ja sieht sich um.>\n\nDieser Ort is' die Geisterwelt! Das is' das erste Mal, dass ich hier in Fleisch und Blut herumlaufe.\n\nSieht so aus, als ob unser Weg zurück blockiert is' und unsere Beute weg is'. Wir müss'n wohl diesen Oger find'n, wenn wir hier abhau'n woll'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[34382] = { id = 34382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grand Warlock Duress" }
quests[34392] = { id = 34392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende des Ansturms", description = "\"Beschützt Gul'dan und seinen Schattenrat mit eurem Leben! Das Portal funktioniert nicht ohne die Teufelsmagie unserer Gefangenen. Wenn ihr versagt, wird alles, was euch lieb ist, sich in Asche verwandeln.\n\n-Grommash Höllschrei.\"\n\nDie Eiserne Horde hat offenbar wichtige Gefangene in ihrer Gewalt, um das Portal offen zu halten. Durchsucht die Spitzen in der Nähe!", sourceObjective = "Deaktiviert die zwei Teufelsspitzen des Dunklen Portals.", completion = "Das Portal ist geschwächt, doch weiterhin offen.\n\nEs gibt nur noch eine Möglichkeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34393] = { id = 34393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft des Portals", description = "Dieses Portal wird von Energien versorgt, die weder mechanischer noch arkaner Natur sind.\n\nSchaut Euch um, {name}. Die gemarterten Seelen der getöteten Gefangenen werden direkt in das Herz des Portals geleitet.\n\nGul'dan ist der Schlüssel, alle Seelen werden durch ihn kanalisiert.\n\nFindet einen Weg in die Kammer unter uns und tut, was auch immer getan werden muss, um Gul'dan aufzuhalten. Ihr seid unsere letzte Hoffnung, {name}.", sourceObjective = "Betretet die Seelenmaschine unterhalb des Dunklen Portals und legt dann das Dunkle Portal still.", progress = "Geht nun! Leben sind in Gefahr!", completion = "Gul'dan... frei. Das ist nicht der Sieg, den ich erhofft hatte.\n\nWegen unserer Taten ist Gul'dan jetzt vielleicht frei, doch würde ich seine Freiheit liebend gern gegen die Leben der Unschuldigen auf der anderen Seite des Portals eintauschen. Ihr habt weise gehandelt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34397] = { id = 34397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtflut brechen", description = "Dieses lächerliche Häufchen Elend hat all seine Gefährten verraten. Ein Schlag in den Nacken war alles, was nötig war.\n\nFindet die Anführer dieser Operation und bringt mir ihre Köpfe. Haratha wird Euch bei Eurer Aufgabe begleiten.", sourceObjective = "Beseitigt die Führung der Nachtflut.", completion = "Jetzt, da ihre Anführer tot sind, wird diese Operation sicherlich scheitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[34398] = { id = 34398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: Das Dunkle Portal", description = "Erzmagier Khadgar, Held des Zweiten Krieges, stellt ein Bündnis der stärksten Kämpfer von Azeroth zusammen, um durch das Dunkle Portal zu treten und zu verhindern, dass die Eiserne Horde in Azeroth einfällt.\n\nKämpfer, die unsterblichen Ruhm erlangen möchten, finden Khadgar am Fuße des Dunklen Portals in den Verwüsteten Landen.\n\nSicherheit nicht gewährleistet.", sourceObjective = "Sprecht mit Erzmagier Khadgar am Fuße des Dunklen Portals in den Verwüsteten Landen.", completion = "Meiner Meinung nach sind wir am richtigen Ort gelandet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34399] = { id = 34399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probleme in der Mine", description = "Es gibt Probleme in der Jorunmine!\n\nWir haben dort kürzlich einen außergewöhnlich großen und mächtigen Arkankristall gefunden. Allerdings ist dabei etwas schrecklich schiefgegangen, und jetzt strömt die Energie dieses Kristalls durch die Mine.\n\nDie Auchenai haben bereits ihre Verteidiger in die Mine entsandt, um uns zu unterstützen.\n\nSprecht bitte mit Verteidiger Doruu in der Mine. Er wird sicher wissen, wie Ihr helfen könnt.", sourceObjective = "Sprecht mit Verteidiger Doruu.", completion = "Die Verteidiger heißen Euch willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34400] = { id = 34400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasende Manaschlinger", description = "In Talador gibt es eine seltene Art Motten, die man \"Manaschlinger\" nennt. Diese Motten ernähren sich von Arkankristallstaub aus den Minen.\n\nNormalerweise stellen diese Motten nur ein gelegentliches, kleineres Ärgernis dar. Aber in letzter Zeit haben sie sich so mit der intensiven arkanen Energie, die der Mine entströmt, vollgeschlagen, dass sie richtiggehend angriffslustig geworden sind.\n\nAus diesem Grund habe ich einen Kristall so vorbereitet, dass er arkane Energie ableitet. Bitte wendet diesen Kristall auf die rasenden Manaschlinger an, um sie zu beruhigen.", sourceObjective = "Wendet den Arkanableiter auf 8 rasende Manaschlinger an.", completion = "Ich danke Euch, {name}. Diese Motten sind normalerweise sehr friedfertig und verdienen Gnade.", sourceObjectiveStatus = "unverified-source-field" }
quests[34401] = { id = 34401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Essenz", description = "Kaelynara wird nicht aufhören, bis sie dem Kristall das letzte bisschen arkane Energie entzogen hat... Und dadurch wird sie die ganze Mine zerstören. Der arkane Schild, mit dem sie sich schützt, kann mit normalen Mitteln nicht durchdrungen werden, aber ich habe einen Plan.\n\nWenn mir ein entsprechender Fokussierkristall zur Verfügung stünde, der mächtig genug wäre, um den Schild für kurze Zeit außer Gefecht zu setzen, könnte Kaelynara selbst erledigt werden.\n\nZum Glück sind wir hier genau richtig, um so etwas zu bauen. Bringt mir bitte als Erstes etwas arkane Essenz von den wilden Kreaturen in dieser Mine.", sourceObjective = "Beschafft 6 arkane Essenzen.", progress = "Habt Ihr die arkane Essenz für mich besorgen können?", completion = "Das reicht vollkommen, {name}. Jetzt brauchen wir nur noch einen geeigneten Kristall...", sourceObjectiveStatus = "unverified-source-field" }
quests[34402] = { id = 34402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Wölfen und Kriegern", description = "Die Rückkehr so vieler meiner Leute ist ein Segen, und ich danke Euch für Euer Mitwirken bei ihrer Rettung.\n\nKommt, reitet mit mir. Wir haben viel zu besprechen.", sourceObjective = "Reitet mit Durotan.", completion = "Dieses Land sollte unseren Ansprüchen mehr als genügen. Ich überlasse Euch die Entscheidung, wie man es am Besten nutzen kann, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[34403] = { id = 34403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Essenz", description = "Kaelynaras Durst nach arkaner Macht hat sie verzehrt, und sie bedroht die Sicherheit aller in dieser Mine. Sie muss aufgehalten werden.\n\nLeider können wir nichts gegen sie ausrichten, solange ihr Schild sie schützt. Wir müssen einen Weg finden, ihren Schildzauber zu durchbrechen.\n\nVielleicht könnte ich einen Fokussierkristall bauen und den Schutz ihres Schildes schwächen... Ich möchte, dass Ihr in der Kristallmine nach den benötigten Komponenten sucht.\n\nAls Erstes benötige ich arkane Essenz von den Arkangespenstern und Kristallwütern in der Mine.", sourceObjective = "Beschafft 6 arkane Essenzen.", progress = "Habt Ihr schon genügend arkane Essenzen gesammelt?", completion = "Gute Arbeit, {name}. Die Menge arkane Essenz sollte ausreichen. Jetzt brauchen wir nur noch einen geeigneten Kristall...", sourceObjectiveStatus = "unverified-source-field" }
quests[34404] = { id = 34404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnlich mächtige Kristalle", description = "Arkankristalle dieser Größe und Potenz sind selbst auf Draenor nicht leicht zu finden. Es ist also kein Zufall, dass die Draenei Shattrath und Auchindoun in unmittelbarer Nähe zu dieser Mine errichtet haben.\n\nIch würde gern mehr über diese besonderen Kristalle und ihre arkanen Fähigkeiten lernen.\n\nWenn Ihr mir einige unbearbeitete Kraftkristalle bringen könnt, werde ich Euch für Eure Mühen angemessen belohnen.", sourceObjective = "Sammelt 10 unbearbeitete Kraftkristalle.", progress = "Habt Ihr schon die unbearbeiteten Kraftkristalle besorgt, die ich für die Forschung brauche?", completion = "Die Kristalle in dieser Mine sind wirklich einzigartig. Durch genaue Tests der von Euch gelieferten Proben sollte sich der Grund dafür herausfinden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34406] = { id = 34406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene des Chaos", description = "Nicht alle der Draenei-Minenarbeiter haben es nach draußen geschafft, als das Chaos ausbrach, {name}. Viele von ihnen sind verletzt und noch immer in der Mine gefangen.\n\nDurch Kaelynaras Ausbruch scheint sich die Hölle selbst aufgetan zu haben. Die freigesetzte Energie hat Arkangespenster hervorgebracht, die alles und jeden angreifen. Die zuvor unter der Oberfläche schlummernden Elementare erheben sich aufgebracht und gefährlich aus den Felsen.\n\nBitte findet so viele verletzte Minenarbeiter wie möglich und bringt sie in Sicherheit.", sourceObjective = "Rettet 8 verletzte Minenarbeiter.", completion = "Vielen Dank, dass Ihr die Arbeiter sicher aus der Mine gebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34407] = { id = 34407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stellung halten", description = "Es ist gut, Euch wiederzusehen, Champion.\n\nDämonen greifen Auchindoun an und wir können uns kaum gegen sie behaupten.\n\nWir müssen unsere Frontlinie weiter nach vorne verschieben, ansonsten erreichen unsere Verluste kritische Ausmaße.\n\nWenn Ihr uns helfen wollt, dann schiebt Eure Klinge in die Schlünder dieser widerwärtigen Kreaturen.", sourceObjective = "Tötet 15 Dämonen an der Brennenden Front.", completion = "Ich hoffe, wir sind genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[34409] = { id = 34409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Krähen unterwegs", description = "Unsere Druiden haben ein weit gefächertes Spähernetzwerk in Gorgrond etabliert, um die Ergebnisse Eurer Berichte aus Nagrand weiter zu verfolgen.\n\nWir haben verdächtige Ausgrabungsarbeiten der Eisernen Horde in der Nähe einiger Salzseen an der Westküste Gorgronds ausfindig gemacht.\n\nWir haben Grund zu der Annahme, dass diese Orcs tief in der Wüste hinter einem wertvollen Artefakt her sind.\n\nIch werde eine kleine Truppe für einen konzentrierten, gezielten Angriff zusammenstellen, und ich hätte Euch gern dabei.", sourceObjective = "Sprecht mit Thisalee Krähe an der Horizontklippe in Gorgrond.", completion = "Seid gegrüßt, {class}. Seid Ihr der Kommandant der Garnison?\n\n\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[34410] = { id = 34410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schlagende Herz", description = "Eines ist sicher. Wir besitzen jetzt einen Gegenstand, der für die Eiserne Horde sehr wichtig ist.\n\nWir sollten dieses... \"Herz von Gorgorek\" besser sofort in Sicherheit bringen.", sourceObjective = "Bringt das Herz von Gorgorek zu Morthis Flügelraunen in Eurer Garnison.", completion = "Noch nie in meinen ganzen Jahren habe ich so etwas gesehen, {name}. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[34411] = { id = 34411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreaturschatz: Schleimkönig" }
quests[34412] = { id = 34412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreaturschatz: Knarlkiefer" }
quests[34413] = { id = 34413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumberstruck" }
quests[34414] = { id = 34414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Riese An'dure", description = "Um Kaelynaras arkanen Schild durchdringen zu können, benötigen wir einen Fokussierkristall von außergewöhnlicher Stärke und Güte.\n\nIm Innern der Mine hält sich ein Kristallriese auf, den die Draenei \"An'dure\" nennen. Dieser Riese hat jahrzehntelang unter dem Fels geschlafen, wurde aber durch Kaelynaras Rücksichtslosigkeit erweckt.\n\nDas Herz eines Kristallriesen ist ein wahrhaft mächtiges Artefakt. Besiegt An'dure und kehrt dann mit dem Kristallriesenherz zu mir zurück. Mit dem Herz hätte ich dann alle Komponenten, um den Fokussierkristall zu bauen!", sourceObjective = "Beschafft das Kristallriesenherz.", progress = "Habt Ihr das Kristallriesenherz?", completion = "Ausgezeichnet. Nur einen kleinen Moment. Ich werde sofort den Fokussierkristall vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34415] = { id = 34415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Riese An'dure", description = "Um Kaelynaras arkanen Schild durchdringen zu können, benötigen wir einen Fokussierkristall von außergewöhnlicher Stärke und Güte.\n\nIm Innern der Mine hält sich ein Kristallriese auf, den die Draenei \"An'dure\" nennen. Dieser Riese hat jahrzehntelang unter dem Fels geschlafen, aber durch das von Kaelynara verursachte Chaos ist er jetzt erwacht.\n\nDas Herz eines Kristallriesen ist ein wahrhaft mächtiges Artefakt. Besiegt An'dure und kehrt dann mit dem Kristallriesenherz zu mir zurück.\n\nSobald ihr zurückkommt, werde ich den Fokussierkristall bauen und gemeinsam werden wir Kaelynara aufhalten!", sourceObjective = "Beschafft das Kristallriesenherz.", progress = "Habt Ihr das Kristallriesenherz?", completion = "Es ist immer traurig, wenn ein solch mächtiges Lebewesen sterben muss. Aber An'dure war eine Gefahr für alle in der Mine. Das Kristallriesenherz wird uns dabei helfen, wieder für Sicherheit in der Jorunmine zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34418] = { id = 34418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stellung halten", description = "Auchindoun wird angegriffen!\n\nDie Auchenai sind tapfere Krieger, aber gegen die endlosen Horden der Dämonen kommen auch sie nicht allein an. Wir sind hier, um zu verhindern, dass die Legion Draenor überrennt. Nur gemeinsam haben wir in diesem Kampf überhaupt eine Chance.\n\nIch möchte, dass Ihr die Anzahl der Dämonen reduziert, damit sich unsere Truppen neu formieren und die Brennende Front angreifen können.\n\nWir werden ihre Offensive hier und jetzt beenden!", sourceObjective = "Tötet 15 Dämonen an der Brennenden Front.", completion = "Dank Eures Einsatzes haben unsere Truppen eine Verschnaufpause bekommen, um sich jetzt der völligen Beseitigung der Bedrohung zu stellen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[34420] = { id = 34420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Krieges", description = "Sie sprachen von einer Selbstmordmission, doch heute wird es keine sinnlose Verschwendung von Leben geben.\n\nAlle mir nach!", sourceObjective = "Folgt Erzmagier Khadgar.", completion = "Nun da das Dunkle Portal deaktiviert ist, haben wir eine neue Mission: am Leben bleiben.\n\nWir müssen weitermachen und sei es nur, um denjenigen Ehre zu erweisen, die sich geopfert haben, damit unser Rückzug gesichert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34421] = { id = 34421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeblutet", description = "<Der Orc stößt seine letzten Worte hervor.>\n\nSie hielten uns in Käfigen gefangen. Sie... haben uns das Blut entzogen... für Rituale...\n\n<Der Frostwolforc hustet stark.>\n\n...noch viele...\n\n...mein Volk...\n\n<Der Orc stirbt.>", sourceObjective = "Befreit die Sklaven aus den 2 Käfigen des Blutenden Auges in Herzblut.", completion = "Gut gemacht, {name}.\n\nSie sind vielleicht verletzt, halb verhungert und schlecht ausgerüstet... aber keine Klinge ist so scharf wie ein rachedurstiger Geist, keine Rüstung so dick wie ein rechtschaffenes Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[34422] = { id = 34422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuereifer", description = "Wir können hier nicht ewig bleiben. Wir MÜSSEN weiter. Aber zunächst brauchen wir eine Ablenkung.\n\n<Khadgar beschwört einen kleinen Edelstein.>\n\nDieser Edelstein sollte alles Brennbare, dem Ihr Euch nähert, in Flammen aufgehen lassen. Mit Euren Fähigkeiten – und etwas Glück – wird es Euch vielleicht gelingen, die Aufmerksamkeit der Orcs des Blutenden Auges von unserer Gruppe abzulenken.", sourceObjective = "Benutzt die Lucifriumperle, um 8 Hütten des Blutenden Auges zu zerstören.", completion = "Vom Regen in die taufrischen Wälder.\n\nAtmet tief durch und dann macht Euch bereit, {name}. Es bleibt nicht viel Zeit zum Verschnaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34423] = { id = 34423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Altar", description = "Seht Ihr den Altar dort unten? Auf seiner Spitze befindet sich ein magisches Auge und ich fürchte, dass es unsere Gruppe töten wird, wenn es uns erblickt.\n\nLenkt dieses Auge ab, {name}. Sorgt für Unruhe, tötet ein paar Ritualisten, tut, was auch immer Ihr tun müsst – solange Ihr das Ding nur lange genug beschäftigt, damit ich die anderen an ihm vorbeiführen kann.\n\n<Khadgar wirft einen Blick über seine Schulter.>\n\nNehmt diesen bärenstarken Orc mit. Den, der nicht Thrall ist.", sourceObjective = "Sprecht mit Ariok und helft ihm dann, das Auge von Kilrogg abzulenken.", completion = "<Khadgar sieht besorgt aus.>\n\nNein, wir können nicht auf Ariok warten. Er wusste, worauf er sich einlassen würde.\n\nSein Opfer soll nicht umsonst gewesen sein. Wir müssen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[34425] = { id = 34425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Übungsplatz von Kargathar", description = "Die Orcs in diesem Gebiet sehen aus, als würden sie zur Zerschmetterten Hand gehören. Man erkennt es an ihren Händen.\n\nLasst uns zu den anderen stoßen. Wir müssen einen Weg hinaus finden.", sourceObjective = "Folgt Khadgar.", completion = "Wir werden diese Stellung erst einmal halten. Wir müssen den befreiten Gefangenen ein wenig Zeit zum Durchatmen gönnen.\n\nEs ist keine ideale Position, also werden wir bald wieder aufbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34426] = { id = 34426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yrel" }
quests[34427] = { id = 34427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein möglicher Verbündeter", description = "Einer der gefangenen Orcs erhält eine... Vorzugsbehandlung, wenn man das so sagen kann. Während die anderen gefesselt und gefoltert werden, ist dieser an einen Pfahl gebunden und wird zur Unterhaltung seiner Häscher verbrannt.\n\nSetzt diesen Runenstein ein. Er sollte mit dem Feuerring, der den Orc umgibt, leicht fertigwerden.", sourceObjective = "Benutzt den Frostwirbelfokus in der Nähe des Rings der Flammen auf dem Übungsplatz von Kargathar, um Scharfseher Drek'Thar zu befreien.", completion = "Ich schulde Euch mein Leben, Fremder. Ich biete Euch und Eurer Begleitung meine Unterstützung an. Zusammen schaffen wir es vielleicht lebend aus diesem Dschungel hinaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[34429] = { id = 34429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgerundet auf Hundert", description = "Ich sehe nur einen Weg aus dieser Falle heraus, {name}, und der führt mitten durch diese Arena.\n\nDas könnte unser Ende bedeuten.", sourceObjective = "Überlebt Kargaths Arena.", completion = "Ihr seid noch am Leben? Gut.\n\nDer Einsturz der Höhle wird sie nur eine kurze Weile aufhalten. Wir müssen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[34431] = { id = 34431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Schatten", description = "Die bösen Orcs haben versucht, mich zu fangen, aber ich habe mich davongeschlichen. Ich bin gut im Verstecken.\n\nAlle bösen Orcs sind böse, aber ich habe mir die Namen der gemeinsten gemerkt, nur falls jemand kommt und mich rettet.\n\n<Luuka holt tief Luft.>\n\nUngra, Gurran und... ähm... oh! Ankova.\n\nWerdet Ihr mich vor ihnen beschützen?", sourceObjective = "Tötet Ungra, Zuchtmeister Gurran und Ankova die Gefallene.", completion = "Gut gemacht.\n\nHaltet Euch bereit für den Aufbruch. Wir haben möglicherweise das Überraschungsmoment in dieser Höhle auf unserer Seite, doch dieser Vorteil wird nicht von Dauer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[34432] = { id = 34432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenmondklan", description = "Wir werden die verwundeten Gefangenen beschützen und sichergehen, dass Kargath es nicht durch das Geröll schafft. Geht vor und räumt die Höhle, {name}.", sourceObjective = "Vernichtet 10 Schattenmondorcs oder Leerenwölfe in den Schattenhallen.", completion = "Ihr kämpft außergewöhnlich gut, {name}... besser, als ich je zu hoffen gewagt habe.\n\nDa die Orcs aus dem Weg geräumt sind, sollten Khadgar und Maraad jetzt in der Lage sein, den Rest unserer Gruppe sicher durch die Höhle zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34434] = { id = 34434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yrel", description = "Verzeiht mir, ich bin ein wenig durcheinander – ich habe noch nie jemanden getötet.\n\nIch heiße Yrel und bin eine Schülerin aus Karabor.\n\nIhr sagt, Ihr hättet eine ARMEE bei Euch? Das Licht wacht heute scheinbar wirklich über mich.\n\nDann werde ich Euch folgen. Geht voran, {name}.", sourceObjective = "Bringt Yrel in Sicherheit.", completion = "Da oben – das ist Keli'dan der Zerstörer. Zweifellos weiß er über unsere Anwesenheit Bescheid und versucht, seinem Kriegsherrn von unserem Gefängnisausbruch zu erzählen.\n\nWir müssen ihn ausschalten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34435] = { id = 34435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Ga'nar" }
quests[34436] = { id = 34436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keli'dan der Zerstörer", description = "Einer von Ner'zhuls Gehilfen ist noch übrig. Er befindet sich weiter vorne und der Höhlenausgang liegt nicht weit hinter ihm.\n\nIch werde zurückgehen und Khadgar sagen, dass die Höhle sicher ist. Wir treffen uns, wenn Ihr Euch um Keli'dan gekümmert habt!", sourceObjective = "Tötet Keli'dan den Zerstörer.", completion = "Gute Arbeit in der Höhle, aber noch ist keine Zeit zum Ausruhen.\n\nWir haben die Initiative und müssen in Bewegung bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34437] = { id = 34437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Frostwolf", description = "Ich schaffe es allein zurück zu Drek'Thar... nachdem ich diesen stinkenden Spaten durch ein paar Schwarzfelsmägen gerammt habe.", sourceObjective = "Sprecht mit Scharfseher Drek'Thar am Schwarzfelssteinbruch im Tanaandschungel.", completion = "Habt Dank, {name}. Unser Häuptling Durotan wird sich freuen zu hören, dass Ga'nar am Leben ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34438] = { id = 34438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was gewaltige Panzer angeht..." }
quests[34439] = { id = 34439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um die Schmiede", description = "Unsere Truppen sind voll bewaffnet. Zeit, anzugreifen!\n\nSchlagt ohne zu zögern und zielsicher zu, {name}!", sourceObjective = "Tötet 15 Orcs des Schwarzfelsklans und 3 Ogronkriegsschläger.", completion = "Gut, dass Ihr höher gelegenes Gelände erreicht habt.\n\nSchaut Euch den Damm an!", sourceObjectiveStatus = "unverified-source-field" }
quests[34440] = { id = 34440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "MARKIERUNG: Khadgar verlässt das Portal" }
quests[34442] = { id = 34442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ga'nar vom Frostwolfklan", description = "Wir müssen weiterziehen, wir dürfen keine Zeit verschwenden!\n\nEiner der Ältesten meines Klans, Ga'nar, ist irgendwo da draußen. Ich kann ihn spüren, aber ich kann ihn nicht finden.\n\nHaltet die Augen nach Ga'nar offen. Er ist ein Orc mit starkem Willen. In Gefangenschaft würde er schwach werden.", sourceObjective = "Sucht nach Ga'nar.", completion = "<Die Lippen des Orcs verzerren sich und zittern vor unterdrückter Wut.>\n\nWer seid Ihr?\n\nWartet, was sagt Ihr da? Drek'Thar ist hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[34445] = { id = 34445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmack von Eisen", description = "So wie ich das sehe, gibt es zwei Wege, diesen Panzer davon abzuhalten, durch das Portal zu kommen: den Panzer kaputtmachen oder das verflixte Portal mit eben diesem Panzer IN DIE LUFT JAGEN!\n\nIch krieg das Ding zum Laufen, ich brauch bloß Zeit. Besetzt den Steuerbord-Geschützturm und haltet mir den Rücken frei.", sourceObjective = "Betretet den Seitenturm des Weltenbrechers und vernichtet 200 Truppen der Eisernen Horde.", progress = "Fast geschafft, {name}.", completion = "Gul'dan auszuschalten, das ist die eine Sache, aber das ganze verdammte Portal in die Luft zu jagen? Das ist ganz meine Art von Lösung.\n\nIch glaube, wir sollten jetzt besser abhauen, bevor diese Streitmacht uns erwischt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34446] = { id = 34446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zielgerade", description = "Wenn sie vorher noch nicht wütend waren, dann sind sie es jetzt ganz sicher. Oben auf diesem Panzer überleben wir keine Minute!\n\nSchlagen wir uns zu den anderen durch und dann nichts wie weg hier!!", sourceObjective = "Begebt Euch zu den Docks.", completion = "Kaum einer hätte es geglaubt, aber hier stehen wir. Immer noch am Leben, mit einer ganzen Streitmacht auf unseren Fersen.\n\nUnser Schiff wartet auf uns. Sollen wir in See stechen?", sourceObjectiveStatus = "unverified-source-field" }
quests[34447] = { id = 34447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaelynara Sonnenjäger", description = "Der Fokussierkristall ist fertig, {name}. Wenn Ihr bereit seid, werde ich ihn verwenden, um Kaelynaras Schild zu durchbrechen.\n\nEs ist allerdings nicht sicher genug, sie im Innern der Mine anzugreifen. Also werde ich uns an einen sicheren Ort außerhalb der Jorunmine teleportieren, sobald ihr Schild außer Gefecht ist. Es wird viel einfacher sein, sie zu besiegen, wenn sie weit vom Kristall entfernt ist.\n\nSprecht mich einfach an, wenn Ihr bereit seid, die Aktion zu starten.", sourceObjective = "Konfrontiert Kaelynara Sonnenjäger.", completion = "Ein weiser Ältester meines Ordens sagte mir einst: \"Wahre Kraft liegt in der Stärke, zu handeln, und in der Weisheit, dies im richtigen Moment zu tun.\" Mögen diese Worte und die Erinnerung an Kaelynara Euch auf Euren Reisen begleiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34448] = { id = 34448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaelynara Sonnenjäger", description = "Der Fokussierkristall ist fertig, {name}. Wenn Ihr bereit seid, werde ich ihn verwenden, um Kaelynaras Schild zu durchbrechen.\n\nEs ist allerdings nicht sicher genug, sie im Innern der Mine anzugreifen. Also werde ich uns an einen sicheren Ort außerhalb der Jorunmine teleportieren, sobald ihr Schild außer Gefecht ist. Es wird viel einfacher sein, sie zu besiegen, wenn sie weit vom Kristall entfernt ist.\n\nSprecht mich einfach an, wenn Ihr bereit seid, die Aktion zu starten.", sourceObjective = "Konfrontiert Kaelynara Sonnenjäger.", progress = "Seid Ihr bereit, Euch dem Kampf mit Kaelynaras zu stellen?", completion = "Ein weiser Ältester meines Ordens sagte mir einst: \"Wahre Kraft liegt in der Stärke, zu handeln, und in der Weisheit, dies im richtigen Moment zu tun.\" Mögen diese Worte und die Erinnerung an Kaelynara Euch auf Euren Reisen begleiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34450] = { id = 34450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Rylaks", description = "Ich habe aus unserem kleinen Freund hier noch mehr Informationen herausquetschen können.\n\nDie Nachtflutmatriarchin befindet sich oben auf dem Hügel.\n\nEiner ihrer führenden Ingenieure versucht mit seiner Technologie, die Matriarchin zu zähmen. Wir müssen ihn aufhalten, {name}.", sourceObjective = "Tötet Razz Ricketroz im Nachtflutnest.", completion = "Wir haben auf dieser Insel heute Großes vollbracht, {name}. Ich freue mich auf den Tag, an dem wir wieder gemeinsam jagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[34451] = { id = 34451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager des Sonnenschwurs", description = "Wir müssen nicht mehr mit den Auchenai zusammenarbeiten, Champion. Ich habe ihre höchsten Seelenbinder gebeten, uns weiterhin zu beraten, aber ich glaube, dass das weitere Vorgehen uns selbst überlassen sein sollte.\n\nTrefft mich im Lager des Sonnenschwurs, südöstlich von hier. Ich fühle weitere dämonische Energien in dieser Gegend. Vielleicht können wir die verbleibenden Machtkristallsplitter direkt an ihrer Quelle aufspüren.", sourceObjective = "Trefft Euch mit Lady Liadrin im Lager des Sonnenschwurs in Talador.", completion = "Es gibt noch viel zu tun, bis wir Auchindoun guten Gewissens sich selbst überlassen können, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[34452] = { id = 34452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garten des Lichts", description = "Die brutale Streitmacht der Feinde ist neutralisiert. Jetzt müssen wir mit den Auswirkungen fertig werden und uns auf zukünftige Angriffe vorbereiten. Die Verteidigung von Auchindoun muss noch immer verstärkt werden.\n\nTrefft mich im Garten des Lichts, nur eine kleine Wegstrecke südlich von hier. Wir haben Berichte über weitere dämonische Energien in dieser Gegend erhalten. Und vielleicht können wir die verbleibenden Machtkristallsplitter direkt an ihrer Quelle aufspüren.", sourceObjective = "Trefft Euch mit Exarch Maladaar im Garten des Lichts in Talador.", completion = "Es gibt viel zu tun, Champion. Der Gestank der Legion liegt in der Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[34453] = { id = 34453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Ankunft von Gazlowe" }
quests[34455] = { id = 34455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit ihre Geister", description = "Dieses Gerät verwenden die Goblins, um die Rylaks zu kontrollieren.\n\nEs gibt auf der Steuerung einen Knopf, an dem 'nicht berühren' steht.\n\nBegebt Euch in die Reichweite eines gedankenkontrollierten Rylaks und drückt auf den Knopf.", sourceObjective = "Benutzt das Rylakgedankenkontrollgerät bei gedankenkontrollierten Rylaks.", sourceObjectiveStatus = "unverified-source-field" }
quests[34456] = { id = 34456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Wolfs" }
quests[34458] = { id = 34458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie für die Verteidigung", description = "Die wenigen Seelenpriester, die uns an der Front zur Verfügung stehen, arbeiten fieberhaft an der Verteidigung von Auchindoun. Auf sich allein gestellt werden sie nicht viel länger durchhalten.\n\nSeelenbinderin Tuulani hat sich zum Grab des Lichts aufgemacht, um einen Reserve-Energiepylonen zu holen. Aber sie ist bis jetzt noch nicht zurückgekehrt. Ich möchte, dass Ihr sie findet und sie zusammen mit dem Pylonen sicher hierher zurückgeleitet.", sourceObjective = "Findet Seelenbinderin Tuulani im Grab des Lichts.", completion = "Ihr seht aus, als würdet Ihr verstehen zu kämpfen! Wir müssen von hier verschwinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[34461] = { id = 34461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaserne? Gerne!", description = "Ihr wollt doch sicherlich eine Kaserne bauen. So was brauchen wir, um artgerecht Visagen zu demolieren.\n\nDer erste Schritt besteht darin, dass Ihr die Baupläne findet und erlernt. Ich glaube, ich hab' hier irgendwo ein paar herumliegen.\n\nDanach müsst Ihr einen Bauplatz auswählen. Zeigt ihn uns einfach auf meinem Architektentisch, dann fangen wir sofort damit an, das Ding hochzuziehen.", sourceObjective = "Findet und erlernt den Garnisonsbauplan für eine Kaserne. Benutzt danach den Architektentisch, um Eure Kaserne errichten zu lassen.", progress = "Wählt den Ort, wir bauen sofort!", completion = "Ich glaube, das wird eine richtig gute Kaserne. Sicher wird sich Kriegsmeister Zog darüber beschweren, dass sie größer sein muss, mehr Stacheln braucht... Er liebt Stacheln.", sourceObjectiveStatus = "unverified-source-field" }
quests[34462] = { id = 34462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wind der Veränderung", description = "Kommandant, ich habe schlechte Nachrichten. Olin Umberfell, der Tauren, der mit Euch aus Tanaan entkommen ist, wurde in der Nähe der östlichen Grenze der Garnison überfallen.\n\nJemand sah, wie die Fahlen ihn wegzerrten. Diese gefährlichen und erschreckenden Geschöpfe waren einst Orcs, wenn man den Gerüchten Glauben schenken kann. Jetzt sind sie nur noch Hüllen, kaum lebendes Fleisch, das von dunkler Magie erfüllt ist.\n\nOlin ist einfallsreich, aber sie sind ihm zahlenmäßig überlegen. Ich schlage vor, Ihr reist nach Osten und leitet schnellstmöglich eine Rettungsaktion ein, bevor sie ihn bei lebendigem Leib auffressen... Stück für Stück.", sourceObjective = "Rettet Olin Umberfell.", progress = "Habt Ihr Olin gefunden? War er tot oder lebendig?", completion = "Gut gemacht, Kommandant. Olin hat mir von Eurer Tapferkeit berichtet und angeboten, unter Eurem Befehl zu dienen.\n\nWenn ich Euch dazu einen Rat geben darf: Ihr solltet sein Angebot annehmen. In einem Land wie diesem könnten wir einen Tauren mit seinen Fähigkeiten gut brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34463] = { id = 34463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöser Ring", description = "Dieser elegant gefertigte Ring ist mit kunstvollen Verzierungen und Symbolen bedeckt. Am meisten tritt der Buchstabe \"V\" in einer leuchtenden Rune hervor. Dieser Ring scheint in der Realität zu verblassen und wieder zu erscheinen, als würde er vorwärts und rückwärts durch die Zeit reisen.\n\nJemand in Khadgars Turm könnte an einem solchen Artefakt interessiert sein.", sourceObjective = "Bringt den mysteriösen Ring zu Zooti Zappenduster in Khadgars Turm in Talador.", progress = "Die Zeitmagie ist ein eher junges Forschungsfeld.", completion = "Ah. Na, was habt Ihr denn da? Dieser Ring wird wohl etwas genauer untersucht werden müssen.\n\nAnscheinend hat jemand versucht, durch die Zeit zu reisen, jedoch auf eher rückständige Weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[34464] = { id = 34464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöse Stiefel", description = "Aufwändig mit einem \"V\" verziert, schieben sich diese flackernden Stiefel in Phasen vorwärts und rückwärts in der Zeit.\n\nVielleicht kann jemand in Khadgars Turm ein Licht auf die Herkunft dieser merkwürdigen Stiefel werfen.", sourceObjective = "Bringt die mysteriösen Stiefel zu Zooti Zappenduster in Khadgars Turm in Talador.", progress = "Ich hatte mich schon gefragt, \"wann\" ich Euch wiedersehen würde. Hm...? Hm...? Verstanden?\n\nAlso, solange jemand da war, der sprechen konnte, mussten die Bronzedrachen einfach alle guten Scherze über die Zeit für sich beanspruchen.\n\nJetzt aber gönnen sich die Hüter der Zeit mal eine Ruhepause, und ich bin endlich an der Reihe!", completion = "Diese Stiefel sind wirklich fantastisch! Es war definitiv richtig, sie zu mir zu bringen.\n\nSie versuchen tatsächlich, den Raum, den sie einnehmen, mit dem in einer anderen Zeitlinie auszutauschen.\n\nDas erfordert definitiv weitere Studien.", sourceObjectiveStatus = "unverified-source-field" }
quests[34465] = { id = 34465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöser Hut", description = "Energie strömt von diesem Hut in unsichtbarer Stärke aus. Er summt, als ob er dort, wo er auf dem Boden liegt, rückwärts und vorwärts durch die Zeit driftet.\n\nDas ist die Art von Gegenstand, die jemand in Khadgars Turm sehr interessant finden würde.", sourceObjective = "Bringt den mysteriösen Hut zu Zooti Zappenduster in Khadgars Turm in Talador.", progress = "Es tut richtig gut, endlich mal mein Lieblingsgebiet zu erforschen, ohne von den Bronzedrachen gestört zu werden.", completion = "Also, DAS ist doch mal ein Hut. Seht Ihr, wie er rückwärts und vorwärts durch die Zeit gleitet, als würde jemand immer wieder daran ziehen?\n\nIch würde ihn ja gerne mal aufsetzen. Aber ich habe zu viel Angst, dass es mich dann aus dieser Zeitlinie herausreißen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[34466] = { id = 34466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöser Stab", description = "Fluktuationen in der Realität umgeben diesen Stab in solcher Stärke, dass es schwer ist, irgendwelche Zeichen außer einem großen, verzierten \"V\" an der Spitze zu erkennen.\n\nVielleicht ist Hilfe von jemandem in Khadgars Turm vonnöten, um ihn zu identifizieren.", sourceObjective = "Bringt den mysteriösen Stab zu Zooti Zappenduster in Khadgars Turm in Talador.", progress = "Ich habe viel Zeit mit Feuer und anderen arkanen Küsten verbracht. Das war eine gute Sache. Gibt doch nichts Schöneres, als einen riesigen Feuerball zu schleudern.\n\nAber Zeitzauberei? Das ist noch viel spaßiger!\n\nSie ist wirklich schwer zu beherrschen, aber man hat ja viel Zeit zum Üben.", completion = "Hm... Dieser Stab kommt mir irgendwie bekannt vor. Ich frage mich, ob...\n\nEs war richtig, dass Ihr ihn mir gebracht habt. Ich werde ihn noch etwas weiter untersuchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34469] = { id = 34469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läutern der Seelen", description = "Nicht alle Geister werden durch den Seelenschänder zerstört. Einige Seelen, wie auch ich, schaffen es, mehr oder weniger unversehrt zu überleben. Andere wurden entstellt und wahnsinnig.\n\nBeendet ihr Elend. Nehmt meinen Seelensplitter und läutert sie. Ihre Raserei wird sie für die Auswirkungen seiner Energie blind machen, daher müsst Ihr sie besiegen, bevor Ihr ihn einsetzen könnt.", sourceObjective = "Läutert 10 wahnsinnige Seelen.", completion = "Danke, ich bin froh, dass die Geister von ihren Qualen erlöst wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34470] = { id = 34470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Pale Gone Fishin'" }
quests[34471] = { id = 34471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Glänzende Münze" }
quests[34472] = { id = 34472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporale Gegenüberstellung", description = "Ich glaube, ich weiß nun, wozu die mysteriösen Artefakte gut sind, die Ihr gesammelt habt.\n\nScheinbar versucht jemand, eine Zeitverschiebung auszulösen, indem er diese Gegenstände aus Eurer eigenen Zeitlinie zurück in diese Zeitlinie schickt.\n\nTechnisch gesehen ist das eigentlich nicht möglich. Aber, wer auch immer dahinter steckt, hat wohl tatsächlich einen Weg gefunden.\n\nIch glaube, ich könnte den Reisenden mit einem Ritual zu uns bringen.", sourceObjective = "Wartet, bis Zooti Zappendusters Zeitritual abgeschlossen ist.", completion = "{name}? Seid Ihr das? Fantastisch! Und es hieß, das wäre unmöglich.\n\nEs hieß immer, nur der bronzene Drachenschwarm könne auf diese Weise durch die Welten reisen. Tja! Wer zuletzt lacht, lacht am längsten!", sourceObjectiveStatus = "unverified-source-field" }
quests[34473] = { id = 34473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufzeichnungen des Botschafters" }
quests[34476] = { id = 34476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Schatz: Eingefrorener Schatz" }
quests[34477] = { id = 34477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cyclonic Fury" }
quests[34478] = { id = 34478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein möglicher Verbündeter", description = "Einer der gefangenen Draenei erhält eine... Vorzugsbehandlung, wenn man das so sagen kann. Während die anderen gefesselt und gefoltert werden, ist dieser an einen Pfahl gebunden und wird zur Unterhaltung der Orcs verbrannt.\n\nSetzt diesen Runenstein ein. Er sollte mit dem Feuerring, der den Draenei umgibt, leicht fertigwerden.", sourceObjective = "Benutzt den Frostwirbelfokus in der Nähe des Rings der Flammen auf dem Übungsplatz von Kargathar, um Exarch Maladaar zu befreien.", completion = "Ich schulde Euch mein Leben, Fremder. Ich biete Euch und Eurer Begleitung meine Unterstützung an. Zusammen schaffen wir es vielleicht lebend aus diesem Dschungel hinaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[34483] = { id = 34483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Galzomar" }
