quests[34505] = { id = 34505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotener Gletscher" }
quests[34506] = { id = 34506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonusziel: Tötet Grimmfrostoger", description = "Befreit die Frostwölfe, die von den Grimmfrostogern gefangen gehalten werden." }
quests[34507] = { id = 34507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Gefrorene Frostwolfaxt" }
quests[34508] = { id = 34508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restalaan, Hauptmann der Wache.", description = "Sie haben Aedraa getötet und ihr den Kristall abgenommen! Der Hauptmann der Wache, Restalaan, hat versucht sie aufzuhalten, und sie haben ihn in die Kathedrale verschleppt!\n\nMithilfe dieses einen Kristalls können wir das Herz von Auchindoun wieder vereinigen und die Verteidigungskraft vollständig wiederherstellen! Wir dürfen jetzt nicht versagen.\n\n{name}, jetzt könnt nur noch Ihr diese Aufgabe übernehmen. Ihr müsst Restalaan finden! Er wird wissen, wo sie den Kristall hingebracht haben.", sourceObjective = "Findet Restalaan in Telmor.", completion = "Jetzt ist keine Zeit zum Plaudern. Der Anführer der Bande ist gleich da vorne.", sourceObjectiveStatus = "unverified-source-field" }
quests[34510] = { id = 34510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Katapulte und Grollhuf" }
quests[34511] = { id = 34511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Ogerzug" }
quests[34512] = { id = 34512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Konkurrenz die Krallen ziehen", description = "Diese Saberonmonster haben mich eine Menge Geld gekostet, {class}.\n\nIch bin nicht jemand, der eine Schuld vergisst, und jetzt ist es an der Zeit zu kassieren!\n\nDie Saberon, die uns den meisten Ärger bereitet haben, sind die in Säbelschlund. Sie überfallen immer wieder unsere Warenlieferanten auf der Straße.\n\n<Pyxni grinst.>\n\nEs ist Zeit, dass wir der Konkurrenz die Krallen ziehen. Bringt mir ihre Klauen. Die Besten von ihnen werden wir hier in der Arena als Glücksbringer verkaufen.\n\nWenn der Erlös der Klauen nicht ausreicht, ihre Schulden zu bezahlen, werden wir ihnen auch noch einen Arm und ein Bein berechnen müssen!", sourceObjective = "Sammelt 10 Saberonklauen.", progress = "Habt Ihr die Saberonklauen, um die ich Euch gebeten habe?", completion = "<Pyxni untersucht die Saberonklauen.>\n\nWir werden ein Vermögen verdienen, wenn wir die als Glücksbringer an die ganzen Möchtegerngladiatoren hier in der Arena verkaufen!\n\nVon jetzt an werden es sich die Saberon zweimal überlegen, sich mit dem Dampfdruckkartell anzulegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34513] = { id = 34513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Scharfkralle!", description = "Gesucht wegen Verbrechen an Unschuldigen im Ring der Prüfung!\n\nScharfkralle ist verantwortlich für mehrere Raubzüge und Überfälle auf Reisende auf der Straße bei Säbelschlund.\n\nZuletzt wurde er in der Umgebung der Saberonhöhle gesehen, die als Säbelschlund bekannt ist.\n\nÄußerste Vorsicht ist geboten!\n\nBei Erfüllung wird dieses Kopfgeld von Pyxni Groschenhort vom Dampfdruckkartell ausbezahlt.", sourceObjective = "Besiegt Scharfkralle.", completion = "Ihr habt Euch den Weg in Säbelschlund hinein freigekämpft, Scharfkralle getötet... und überlebt?\n\nDas sind unglaubliche Neuigkeiten!\n\nDie Straßen werden viel sicherer sein, jetzt, wo er tot ist! Das bedeutet mehr Geld für mich!\n\nWie versprochen ist hier Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[34514] = { id = 34514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben die Waren!", description = "Die Saberon... es ging ihnen nicht nur um Gefangene...\n\n<Hust>... Sie haben auch alle Waren mitgenommen.\n\nEntführung ist eine Sache... aber einem Goblin die Waren stehlen? Das macht die Sache persönlich!\n\n<Hust>... Pyxni wird nicht glücklich sein, bis Ihr alle gestohlenen Waren wiederbeschafft habt. Kämpft Euch einen Weg nach Säbelschlund hinein und stehlt unsere ganzen Waren zurück.\n\nWenn Ihr es geschafft habt, geht zu Pyxni im Ring der Prüfung.\n\nSie wird dafür sorgen, dass es sich für Euch lohnt...", sourceObjective = "Beschafft 10 gestohlene Waren.", progress = "Greezlex hat Euch erzählt, die Saberon hätten unsere Waren gestohlen?\n\nNun, warum steht Ihr dann noch hier herum? Schafft Euren Hintern nach Säbelschlund und holt sie zurück!\n\nZeit ist Geld!", completion = "Ihr habt die Waren wiederbeschafft? Fantastisch!\n\n<Pyxni durchwühlt die Taschen.>\n\nEs ist alles da! Ich wusste, ich kann mich auf Euch verlassen! Hier, nehmt die Belohnung.\n\nIhr habt sie verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[34515] = { id = 34515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobnapping", description = "Wir haben den Überfall absolut nicht kommen sehen...\n\nDie Saberon haben uns so schnell und hart erwischt, dass wir kaum Zeit hatten, einen klaren Gedanken zu fassen.\n\nDiese übergroßen Bastarde haben die anderen weggeschleift und mich hier zum Sterben zurückgelassen... Wahrscheinlich haben sie gedacht, ich wäre dem Tod schon zu nahe.\n\nIch habe gehört, sie mögen ihr Fleisch am liebsten frisch...\n<Hust>... also, ich gehe nicht so leicht hops!\n\nMacht Euch um mich keine Sorgen... <hust>... Ich habe schon Schlimmeres durchgemacht! Ihr werdet jedoch nach Säbelschlund gehen müssen, um die anderen Händler rauszuholen.\n\nSie haben sie wahrscheinlich alle dort eingesperrt...", sourceObjective = "Rettet 6 Goblinhändler.", completion = "Ihr habt alle gefangenen Händler aus Säbelschlund herausgeholt? Fantastisch!\n\nJetzt schulden sie mir etwas, und ich bin niemand, der eine Schuld verfallen lässt! Was Euch angeht, nehmt diese Belohnung für Eure Bemühungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34516] = { id = 34516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Schatz!", description = "Ihr müsst mir helfen!\n\nIch hatte mich auf dem Wagen mit Handelsgütern versteckt, der da hinten auf der Straße überfallen wurde. Ich konnte wegschleichen, bevor die Saberon mich entdeckt haben... aber... aber...\n\nSIE HABEN MEINEN WERTVOLLSTEN BESITZ GESTOHLEN!\n\nIhr müsst mir helfen, ihn zurückzubekommen! Ich habe zugesehen, wie sie ihn nach Säbelschlund hinein und diesen riesigen Hügel hinauf gezerrt haben!\n\nWer weiß, was diese dreckigen Saberon damit anstellen?!\n\nBitte, ich bin doch nur ein Kind! Ihr müsst mir doch helfen, oder?", sourceObjective = "Sucht nach Bazwix' gestohlenem Schatz.", completion = "Ihr habt tolle Arbeit geleistet, {name}. Ich hätte mir keinen besseren Assistenten wünschen können!\n\nWie auch immer... Wo ich jetzt meinen Schatz wiederhabe...\n\nIch muss...\n\n...Dinge erledigen... und so.\n\nTschüs!", sourceObjectiveStatus = "unverified-source-field" }
