quests[34558] = { id = 34558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Eurem Befehl", description = "Ich bin froh, dass Ihr hier seid!\n\nFort Wrynn ist fast fertig. Wir müssen nur noch diese letzte Parzelle füllen.\n\nBaros hat uns die Baupläne zweier Gebäude zur Verfügung gestellt, die in diese Lücke passen würden: ein Artillerieturm oder ein arkanes Sanktum.\n\nEs ist Eure Entscheidung, Kommandant. Die Pläne liegen auf dem Zeichentisch, damit Ihr sie prüfen könnt.", sourceObjective = "Entscheidet, welches Gebäude im Außenposten gebaut werden soll.", progress = "Ich stehe zu Diensten.", completion = "Ausgezeichnet. Das wird vollauf genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34559] = { id = 34559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Yaga der Vernarbte", description = "Goren sind gefährlich, besonders in großer Zahl... und erst recht, wenn wir einen blinden, ausgelaugten Schamanen bei uns haben.\n\nGlücklicherweise leben Goren nicht sehr lange. Unglücklicherweise vermehren sie sich aber schnell und wachsen noch schneller.\n\nWenn wir das hier schaffen wollen, müssen wir ihre Brutmutter finden. Wenn wir sie töten und ihre Eier vernichten, sollte das den Ansturm der Goren bremsen. Überprüft die Löcher in der Nähe des Tors zur Schmiede, ich werde sie solange von Drek'Thars Fährte ablenken." }
quests[34560] = { id = 34560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenal" }
quests[34561] = { id = 34561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierturm" }
quests[34562] = { id = 34562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trigger Teron'gor Defense Spawns" }
quests[34563] = { id = 34563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinbruch des Anstoßes", description = "Nachdem der Artillerieturm fertig gestellt ist, bräuchten wir jemanden mit Erfahrung, der hier die Leitung übernehmen kann.\n\nIch habe gehört, dass Ared, einer der besten Schmiede Shattraths, dem Untergang der Stadt entkommen ist. Er müsste direkt außerhalb der nördlichen Mauer bei den anderen Flüchtlingen zu finden sein.\n\nVielleicht könnt Ihr ihn ja davon überzeugen, für uns zu arbeiten.", sourceObjective = "Sprecht mit Lehrling Miall direkt außerhalb von Fort Wrynn in Talador.", progress = "Wir müssen jemanden finden, der den Laden hier zum Laufen bringt. Sonst werden wir auch nicht viel produzieren.", completion = "Ihr seid der Kommandant dieses Forts, oder?\n\nMein Meister wollte sich Eurem Kampf zur Rückeroberung unserer Heimat anschließen, doch er wurde krank und... Es tut mir leid, er war ein großer Draenei und ich werde sein Erbe fortsetzen.\n\nEuer neues Gebäude gäbe mir die Möglichkeit, die Vision meines Meisters zu vollenden und seines Todes zu gedenken.\n\nWenn Ihr mir dies gestattet, werde ich Euch dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34564] = { id = 34564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Unbekannt", description = "Teron'gor und Gul'dan verließen gerade das Portal, als ich ankam... und ich... ich weiß, dass ich ihnen nicht gewachsen bin.\n\nIch werde das Portal so lange offen halten wie ich kann, doch es liegt an Euch, ihnen den Todesstoß zu versetzen.\n\nUnser Schicksal liegt in Euren Händen, {name}.", sourceObjective = "Vernichtet Mongrethod in den Trümmern von Xandros.", completion = "Teron'gor und Gul'dan... sie haben alle abgeschlachtet...\n\n...und dann, dann... verschwanden sie einfach... in die Schatten...\n\nWoher wussten sie nur, wohin sie gehen mussten?", sourceObjectiveStatus = "unverified-source-field" }
quests[34565] = { id = 34565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taladorfeldzug", description = "<Kommandant/Kommandantin>, es gibt hier ein kleines Problem.\nWir haben in Talador eine Position für den Außenposten gefunden. Aber die Gruppe, die ihn errichten sollte, ist darüber in Streit geraten, was wir bauen sollen. Wenn dieser Konflikt nicht schnellstens geklärt wird, könnte das unsere Pläne signifikant verzögern.\n\nBitte kommt per Greif nach Talador und sprecht mit Vorarbeiter Eksos, bevor die Situation außer Kontrolle gerät." }
quests[34566] = { id = 34566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Eurem Befehl", description = "Kommandant, der Außenposten ist fast vollständig in Betrieb.\n\nGazlowe hat uns zwei verschiedene Baupläne für diese letzte Parzelle zur Verfügung gestellt: ein Arsenal oder ein arkanes Sanktum.\n\nBeides würde uns zusätzliche Feuerkraft verschaffen, die wir benötigen, um das Vorrücken der Eisernen Horde aufzuhalten.\n\nDie Pläne liegen auf dem Zeichentisch. Eure Entscheidung.", sourceObjective = "Werft einen Blick auf den Zeichentisch und entscheidet, welches Gebäude des Außenpostens Ihr errichten wollt.", progress = "Was ist Euer Befehl, Kommandant?", completion = "Wie Ihr befehlt.\n\nFür die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[34567] = { id = 34567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierturm" }
quests[34568] = { id = 34568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenal" }
quests[34569] = { id = 34569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinbruch des Anstoßes", description = "Jetzt, da wir unser Arsenal fertiggestellt haben, fehlt uns nur noch ein tüchtiger Schmied.\n\nVor kurzem haben wir einen Deserteur der Eisernen Horde gefangen genommen. Er behauptet, einer der besten Schmiede des Schwarzfelsklans gewesen zu sein.\n\nNormalerweise würde ich den wahnwitzigen Beteuerungen eines Gefangenen keinen Glauben schenken, aber seine Waffen waren von Meisterhand gefertigt.\n\nKommandant, ich finde, wir sollten sehen, ob er wirklich so gut ist, wie er behauptet.", sourceObjective = "Überzeugt Morketh Klingenschrei, Euch zu helfen.", completion = "Ihr seid derjenige, der hier das Sagen hat, oder? Ich hörte, wie die Wachen über Eure Taten sprachen, und wenn ich Euch nicht vor mir stehen sähe, könnte ich schwören, dass sie gelogen haben.\n\nEs ist schon immer mein Wunsch gewesen, nur die besten Klingen herzustellen und sie von den stärksten Kriegern führen zu lassen. Ich sehe bereits, dass Ihr jemand seid, dem ich gerne meine Waffen überlasse.\n\nWenn Ihr mir eine Chance gebt, so schwöre ich, dass ich Euch nicht enttäuschen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[34570] = { id = 34570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "Teron'gor und sein Meister Gul'dan waren hier! Ich habe versucht, sie aufzuhalten... aber sie sind durch das dämonische Portal hinter mir entkommen, bevor ich sie fertigmachen konnte!\n\nIch glaube, ich kann das Portal lange genug aktivieren, dass Ihr es betreten könnt. Wir haben keine Möglichkeit herauszufinden, wohin es führt, aber ich befürchte, es könnte Auchindoun sein!\n\nIhr müsst Gul'dan ein für alle Mal aufhalten!" }
quests[34571] = { id = 34571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Jovit mehr", description = "Ared und ich kamen hierher, weil wir einen ordentlichen Vorrat an Metall benötigten, um seine Entwürfe umzusetzen, und eines der besten Metalle ist das Jovit, das aus der Mine von Kuuros Bergwerk stammt. Um den Artillerieturm weiter beliefern zu können, brauche ich dieses Metall.\n\nBedauerlicherweise wurde der Ort kürzlich von einem Rudel Goren überrannt. Daher müsst Ihr Euch den Weg freikämpfen, um an das Erz zu gelangen, bevor sie es vollständig aufgefressen haben.\n\nDas ist nichts, was Euch allzu große Probleme bereiten sollte.", sourceObjective = "Sammelt 12 Brocken Joviterz in Kuuros Bergwerk.", progress = "Wir müssen an das Erz gelangen, bevor diese Goren alles auffressen.", completion = "Die sehen recht gut aus. Ared hätte es geliebt, die in die Finger zu bekommen.\n\n<Miall wischt sich eine Träne weg.>\n\nTut mir leid, das geht mir etwas nahe. Die sind genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[34572] = { id = 34572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschen der Oger", description = "Jetzt, da sie echte Ogermagier haben, haben die Patrouillen und die Aggressivität der Hochfelsoger zugenommen.\n\nWenn ihre Reihen ausgedünnt werden, ist das ein großer Schritt zur Verhinderung einer Rückkehr der Hochfelsoger nach Nagrand.\n\nKehrt danach zu meiner Schwester Mirana zurück, sie sollte weitere Neuigkeiten haben.", sourceObjective = "Tötet 15 Oger bei Mar'goks Wacht.", completion = "Perfekt. Jetzt müssen sie sich mehr auf die Verteidigung ihrer Basis konzentrieren. Hoffentlich normalisieren sich die Dinge da draußen wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[34573] = { id = 34573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iridiumbeschaffung", description = "Ared lehrte mich immer, dass die Reinheit des Metalls der Schlüssel sei. Wenn das Metall nicht rein ist, wird es unter Belastung brechen und niemandem mehr nützen.\n\nFür den Artillerieturm muss ich Metall herstellen, das so rein ist wie das meines Meisters, und dafür benötige ich einen starken Flux.\n\nDer Staub von gemahlenen Iridiumgeoden würde notfalls genügen, doch davon müssen wir erst ein paar finden. Sie sammeln sich meist unterirdisch an, also sucht danach in der Mine von Kuuros Bergwerk.", sourceObjective = "Sammelt 8 Portionen Iridiumstaub von den Iridiumgeoden in Kuuros Bergwerk.", progress = "Ich werde eine Menge Iridiumstaub benötigen, bis das Metall so rein ist, dass es dem Standard meines Meisters auch nur nahe kommt.", completion = "Das wird nicht so gut sein wie das Material, das wir in der Schmiede in Shattrath hatten, doch es wird genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34575] = { id = 34575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritter Schritt: Prophet!", description = "Ihr habt das Schattenmondtal erreicht. Es ist Zeit, dass Ihr mit dem Propheten sprecht.", sourceObjective = "Sprecht mit Prophet Velen beim Schiffswrack der Eisernen Horde im Schattenmondtal.", completion = "<Der Prophet heißt Euch mit einem neugierigen Blick und einem herzlichen Nicken willkommen.>\n\nEs fängt also an.", sourceObjectiveStatus = "unverified-source-field" }
quests[34576] = { id = 34576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iridiumbeschaffung", description = "Einst waren meine Waffen nur für die Besten der Besten, doch jetzt stellt die Eiserne Horde aus minderwertigem Metall Kopien meiner Meisterwerke her, die sie jedem Dahergelaufenen aushändigen.\n\nIch werde ihnen in Eurem Arsenal zeigen, wozu ein echter Schmied fähig ist, doch zuerst benötige ich einen starken Flux, damit das Metall so rein wie möglich wird.\n\nDer Staub gemahlener Iridiumgeoden würde notfalls genügen, doch davon müssen wir erst ein paar finden. Sie sammeln sich meist unterirdisch an, also sucht danach in der Mine von Kuuros Bergwerk.", sourceObjective = "Sammelt 8 Portionen Iridiumstaub von den Iridiumgeoden in Kuuros Bergwerk.", progress = "Ich werde eine Menge Iridiumstaub benötigen, damit das Metall rein genug wird, um meinen Standards auch nur ansatzweise zu genügen.", completion = "Das wird nicht so gut sein wie einige der Mischungen, die wir in den Gießereien des Schwarzfelsklans hatten, doch es wird genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34577] = { id = 34577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Jovit mehr", description = "Um gute Ausrüstung zu schmieden, braucht man hochwertiges Metall. Eines der hochwertigsten Metalle überhaupt ist das Jovit, das man in Kuuros Bergwerk im Osten findet. Um das Arsenal weiter beliefern zu können, brauche ich dieses Metall.\n\nBedauerlicherweise wurde der Ort kürzlich von einem Rudel Goren überrannt. Daher müsst Ihr Euch den Weg freikämpfen, um an das Erz zu gelangen, bevor sie es vollständig aufgefressen haben.\n\nDas ist nichts, was Euch allzu große Probleme bereiten sollte, Kommandant.", sourceObjective = "Sammelt 12 Brocken Joviterz in Kuuros Bergwerk.", progress = "Wir müssen uns das Erz holen, bevor diese verdammten Goren alles auffressen.", completion = "Die Brocken sind groß genug und es ist nicht allzu viel Matrixmaterial darauf.\n\nSie werden genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34578] = { id = 34578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besuch bei den Gordunni", description = "Der Artillerieturm ist jetzt gut mit Jovit versorgt, doch in der Mine ist nicht genug, dass es lange so bleiben wird. Im Süden gibt es einen Berg, der vor dem Zeug nur so überquillt, doch es gibt da ein Problem: Oger!\n\nDie Gordunni leben auf dem Berg und sie haben damit begonnen, Jovit an die Eiserne Horde zu verkaufen.\n\nWir müssen dorthin und uns die Mineralien sichern.\n\nIch packe ein paar Vorräte zusammen, dann treffen wir uns in der Nähe ihrer Festung im Süden.", sourceObjective = "Reist zur Gordalfestung und trefft Euch dort mit Miall.", completion = "Bevor wir aufbrachen, habe ich ein paar Dinge hergestellt, die wir brauchen können: ein paar Rauchgranaten, ein Greifhaken, und ich konnte Thaelin sogar dazu bringen, einen Raketenrucksack zusammenzuzimmern.\n\nIch bin sicher, wir werden für all diese Dinge Verwendung finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34579] = { id = 34579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gasräuber", description = "Zur Herstellung der besten Ausrüstung für Euch benötige ich nicht nur die besten Materialien, ich muss außerdem auch die besten Techniken anwenden.\n\nIm Lauf der Jahre habe ich eine Methode entwickelt, mit der ich Metall deutlich verstärken kann. Doch dafür benötige ich einen exotischen Rohstoff: Gorengas!\n\nDie nahe Mine in Kuuros Bergwerk wurde vor Kurzem von Goren überrannt. Wärt Ihr so nett, dort ein paar Proben für den Vorrat des Arsenals zu nehmen? Tötet einfach einige Goren und lasst diesen Gasextraktor an ihren Kadavern seine Arbeit verrichten.", sourceObjective = "Besorgt Euch 6 Proben Gorengas von Splitterrücken und Verschlingern der Glühschlunde in Kuuros Bergwerk.", completion = "Vielen Dank, Chef, das ist genau das, was ich brauche.\n\nÜbrigens ist Gorengas nur schwer zu bekommen. Wir sollten uns vielleicht noch ein wenig gedulden, bevor wir sie komplett ausräuchern, bis unser Vorrat groß genug ist.\n\nNur so ein Gedanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[34580] = { id = 34580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Flowerpicker" }
quests[34581] = { id = 34581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Flowerpicker Note Found" }
quests[34582] = { id = 34582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuß fassen", description = "Ihr habt also meine Kinder nach Hause gebracht? Ich habe Euch erwartet.\n\nDie Eiserne Horde wird von Tag zu Tag stärker.\n\nIch habe eine große Schlacht vorhergesehen, aber meine Visionen sind undeutlich. Es ist, als ob die Zeit sich selbst überlappt.\n\nEins ist sicher – Eure Anwesenheit hier ist von eminenter Wichtigkeit.", sourceObjective = "Folgt Prophet Velen.", completion = "Das muss genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34583] = { id = 34583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz!", description = "Wir hätten Tanaan ohne Eure Kraft nicht überlebt, {name}. Viele Draenei und die Allianz stehen in Eurer Schuld.\n\nBevor wir zum Dunklen Portal aufgebrochen sind, hat König Wrynn persönlich empfohlen, dass ich Euch die Leitung unserer Einsätze hier in Draenor übertrage. Nachdem ich Euch in Aktion gesehen habe, neige ich dazu, ihm zuzustimmen.\n\nDiese Garnison gehört Euch. Stellt das Banner auf und wir beginnen sofort mit dem Bau, Kommandant.", sourceObjective = "Stellt das Allianzbanner auf.", completion = "Das ist also Draenor? Etwas dunkler, als ich erwartet hatte. Dennoch, nach dem Bau von Sturmwind dürfte dieses Projekt der reinste Spaziergang werden.\n\nNun denn, seid Ihr bereit, anzufangen, Kommandant?", sourceObjectiveStatus = "unverified-source-field" }
quests[34584] = { id = 34584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz sammeln", description = "Einige der kleineren Bäume in der Nähe können unsere Arbeiter schnell fällen.\n\nWir werden Shellys Leuten die harte Arbeit überlassen, doch wenn Ihr wünscht, könnt Ihr die Bäume markieren, mit denen sie anfangen sollen. Wir sollten die ganze Sache damit dann zügig angehen können.", sourceObjective = "Markiert 8 Bäume.", completion = "Perfekt.\n\nDieses Holz wird nicht nur einfach seinen Zweck erfüllen, es wird auch noch fantastisch aussehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34585] = { id = 34585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murenfaust", description = "Ich erhalte Berichte über einen Riesen im Wald.\n\nEinige der Friedensbewahrer von Karabor sind ihm bis zu einer Höhle gefolgt. Ehrlich gesagt glaube ich nicht, dass es unsere Truppen mit der Bestie aufnehmen können.\n\nVielleicht könntet Ihr die Angelegenheit untersuchen? Ich bin mir sicher, die Friedensbewahrer würden die Hilfe zu schätzen wissen.", sourceObjective = "Tötet Murenfaust.", progress = "Habt Ihr den Riesen in der Höhle getötet?", completion = "Jetzt, da der Riese tot ist, ist die Basis eindeutig sicherer.\n\nIhr habt die Friedensbewahrer ziemlich beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34586] = { id = 34586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet Eure Garnison", description = "Ich bin beeindruckt, wie schnell Ihr diese Gruppe zusammengestellt habt, Kommandant.\n\nIch denke es wird Zeit, dass wir ein paar Mauern hochziehen und unsere Basis solide sichern.", sourceObjective = "Errichtet Eure Garnison.", completion = "Die Garnison nimmt langsam wirklich Form an.", sourceObjectiveStatus = "unverified-source-field" }
quests[34587] = { id = 34587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaserne? Gerne!", description = "Ich muss sagen, Kommandant, diese Garnison macht sich so langsam.\n\nWir haben genug Material. Jetzt brauchen wir nur noch den Plan, dann kann ich mit dem Bau der Kaserne beginnen.\n\nHmm... wo habe ich ihn nur hingelegt?", sourceObjective = "Findet und erlernt den Bauplan. Benutzt danach den Architektentisch, um Eure Kaserne errichten zu lassen.", completion = "Wie geht es mit dem Bau der Kaserne voran?", sourceObjectiveStatus = "unverified-source-field" }
quests[34592] = { id = 34592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gronnlingproblem", description = "Das wird ein ganz schönes Stück Arbeit, Euch eine Festung zu bauen, wenn hier in der Gegend Gronnlinge herumtrampeln.\n\nIch glaube kaum, dass einer von uns in der Lage ist, diese Biester zu Fall zu bringen, also müsst Ihr vermutlich selbst Hand anlegen.", sourceObjective = "Tötet 8 Frostfeuergronnlinge.", completion = "Die haben hier auf Draenor aber ganz schön hässliche Biester.", sourceObjectiveStatus = "unverified-source-field" }
quests[34593] = { id = 34593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffsbefehle der Oger beschaffen", description = "Meine Schwester, Mirana, ist als Späherin auf dem oberen Teil des Bergs unterwegs, während ich den unteren Bereich ausspähe. Da sind insbesondere zwei Ogermagier, die im unteren Gebiet eine Menge herumkommandieren.\n\nSie scheinen ein paar Befehle oder Schriftrollen bei sich zu haben, die uns dabei helfen könnten, herauszufinden, was da wirklich vorgeht.\n\nBesorgt diese Informationen und trefft Euch mit meiner Schwester auf der langen Treppe dort oben.", sourceObjective = "Besorgt Crulgoroshs Befehle und Thulgorks Befehle bei Mar'goks Wacht.", progress = "Diese Befehle wären wirklich hilfreich, um das große Ganze zusammenzusetzen.", completion = "Gut, dass Ihr hier seid. Fast hätte man mich da oben umgebracht. Oh, was sind das für Papiere? Das ist ja noch viel schlimmer, als ich befürchtet hatte!", sourceObjectiveStatus = "unverified-source-field" }
quests[34596] = { id = 34596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reglakks Forschung", description = "Diese Oger haben alte Titanenartefakte benutzt, um ein Spezialkommando, genannt Zerstörer, zu verstärken. Dieser Magister Reglakk ist hier, um Möglichkeiten zu finden, den Prozess zu verbessern.\n\nSetzen wir seinen Ritualen dort oben auf dem Berg ein Ende.", sourceObjective = "Gebietet Großmagister Reglakk Einhalt.", completion = "Dieser Teufelsbrecher klang ziemlich zäh! Gut, dass es nur wenige davon gibt.\n\nIhr habt bei Reglakk gute Arbeit geleistet, aber ich bin sicher, dass er sich jetzt wieder in Hochfels verschanzt hat. Jemand muss sich besser früher als später um die Hauptstadt der Oger kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[34597] = { id = 34597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belastende Unterlagen", description = "Diese Kiste steckt voller Schriften und Diagramme, die verdächtig nach Forschungsbemühungen auf dem Gebiet der Nullifikation von Magie aussehen.\n\nEs wäre wohl am besten, wenn Ihr jegliche dieser Bemühungen zunichtemacht, indem Ihr das Forschungsmaterial vernichtet.", sourceObjective = "Vernichtet 8 Kisten mit Forschungsmaterial der Oger bei Mar'goks Wacht.", completion = "Hervorragende Arbeit. Ihr seid wirklich auf Zack. Je weniger diese Oger forschen, desto besser!", sourceObjectiveStatus = "unverified-source-field" }
quests[34598] = { id = 34598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vermisste Karawane", description = "Ich habe ein Problem, und Ihr seht aus, als wärt Ihr genau <der richtige/die richtige:r> {race} für den Auftrag!\n\nGestern sollte eine Warenlieferung ankommen, doch sie ist unauffindbar. Mir gehen hier die Waren aus, und ich brauche jemanden, der für mich herausfindet, was passiert ist!\n\nWenn ich raten soll, würde ich sagen, dass wahrscheinlich die Saberon etwas damit zu tun haben. Diese Rohlinge sind uns schon ein Dorn im Auge, seit wir hier angekommen sind!\n\nSucht auf der Straße in der Nähe von Säbelschlund nach dem Wagen und beeilt Euch! Zeit ist Geld!", sourceObjective = "Sucht nach der vermissten Warenlieferung.", completion = "<Greezlex hebt seinen Kopf, um Euch vom Boden aus anzusehen.>\n\n...Nein! Lasst mich bitte... Ich... wartet...\n\nIhr seid kein Saberon... Hat Pyxni Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[34599] = { id = 34599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Yrel Leave Twilight Glade" }
quests[34600] = { id = 34600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Vorka, Rangari Leave" }
quests[34609] = { id = 34609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tintenherstellung", description = "Wir müssen einen Weg finden, um einen künstlichen Nexus bei Eurem Turm zu erzeugen.\n\nIch weiß, wo wir eine Energiezufuhr dafür herbekommen, doch sie ist schwer bewacht. Wir müssen einen kühlen Kopf bewahren und es richtig angehen.\n\nIch habe einen Plan: eine Schriftrolle der Massenteleportation.\n\nDie Fungusgiganten und Schlurfer da unten sind mit Pusteln übersät, in denen sich eine ölige Substanz befindet. Aus dem Öl könnte ich eine Art Tinte machen, die wir für die Schriftrolle verwenden können.", sourceObjective = "Sammelt 30 pulsierende Pusteln von Sporenseglern und Fungusgiganten in Zangarra.", progress = "Die Riesen sind schwieriger niederzuringen, aber sie haben mehr Pusteln!", completion = "Das ist nicht ganz das, was sie mir in Dalaran beigebracht haben, aber es muss funktionieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[34612] = { id = 34612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schriftrolle rollen", description = "Wir brauchen arkanes Pergament, um die Schriftrolle fertigzustellen.\n\nArkane Energie kommt überall an diesem Nexus vor. Sie hat die Urtume erstarren lassen und sich in ihren Rinden festgesetzt.\n\nWenn wir den wenigen, die noch nicht diesen Funguskreaturen anheimgefallen sind, ein paar Stücke abnehmen können, kann ich sie zu Pergament verarbeiten.", sourceObjective = "Reißt 3 Stück Rinde von schlummernden Urtumen in Zangarra ab.", completion = "Ja, die hier werden sich wunderbar machen! Der Brei daraus wird sich herrlich zu Pergament gefrieren lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34616] = { id = 34616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuberische Raben", description = "Seht Ihr das? Gleich hinter dieser Baumgrenze befindet sich ein riesiger Rabe.\n\nIch gehe da keinen Schritt näher ran. Tatsächlich weiß ich nicht, ob die Männer ausreichend ausgerüstet sind, um mit solch einer Bedrohung fertigzuwerden.\n\nWollt Ihr Euch selbst darum kümmern, Kommandant?\n\nSobald diese Raben fort sind, können wir mehr Truppen in die Wälder entsenden. Damit schlagen wir zwei Fliegen mit einer Klappe... oder vielleicht eher fünf Vögel mit...\n\n<Baros kratzt sich am Kopf, verwirrt von seiner eigenen Analogie.>\n\nIhr wisst schon.", sourceObjective = "Tötet 6 Mondsturzraben.", completion = "Dieser Ort ist voller Überraschungen... schrecklicher Überraschungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34619] = { id = 34619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken fangen", description = "Wir benötigen arkane Energie, um unsere Schriftrolle fertigzustellen. Nur mit ihr lässt sich die Schriftrolle vollenden.\n\nIch habe ein Artefakt, das Energiewirbel unten im Krater einfangen kann. Lasst uns loslegen.", sourceObjective = "Sammelt 3 Arkanvortexe in Zangarra.", completion = "Perfekt! Wir sollten jetzt genug Energie haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34622] = { id = 34622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Ner'zhul Leave" }
quests[34624] = { id = 34624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gasräuber", description = "Um die Entwürfe meines Meisters zu vollenden und den Artillerieturm zu füllen, benötigen wir einen exotischen Rohstoff: Gas aus den Eingeweiden eines Gorens.\n\nDie nahe Mine von Kuuros Bergwerk wurde gerade von diesen Viechern überrannt. Könntet Ihr mir ein paar Proben nehmen? Dieses Zeug ist konzentriert, daher würden schon wenige Proben genügen. Tötet einfach einen Goren und lasst diesen Gasextraktor an seinem Kadaver seine Arbeit verrichten.", sourceObjective = "Besorgt Euch 6 Proben Gorengas von Splitterrücken und Verschlingern der Glühschlunde in Kuuros Bergwerk.", completion = "Vielen Dank! Das ist genau das, was ich brauche.\n\nGorengas ist ziemlich schwer zu bekommen, aber glücklicherweise können wir mit diesem Vorrat ziemlich lange haushalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34631] = { id = 34631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz beim Erzmagier", description = "Ich freue mich, berichten zu dürfen, dass unser arkanes Sanktum einsatzbereit ist, Kommandant!\n\nAlles wurde genau nach dem Bauplan installiert... mit Ausnahme dieser von Baros hingekritzelten Fußnote. \"Nicht vergessen, den Turm mit dem Leyliniennetz zu verbinden!\"\n\nKommandant, ich bin nur ein Vorarbeiter, kein Magier. Ich... habe nicht den blassesten Schimmer, wie ich das machen soll.\n\nWir haben Erzmagier Khadgar und ein paar andere Kirin Tor nicht weit von hier gesichtet. Im Osten war es, in Richtung der Berge. Vielleicht könnten wir sie um Hilfe bitten?", sourceObjective = "Sprecht mit Erzmagier Khadgar in Talador.", completion = "Ah, Ihr habt also ein Arkanes Sanktum errichtet! Wunderbar!\n\nNur das Verbinden mit dem Leyliniennetz bereitet Euch Schwierigkeiten, nehme ich an?", sourceObjectiveStatus = "unverified-source-field" }
quests[34632] = { id = 34632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz beim Erzmagier", description = "Mit Eurem arkanen Sanktum geht es prächtig voran, Kommandant!\n\nAlles wurde genau nach Plan umgesetzt... außer einem kleinen Detail, das Gazlowe ganz unten hingekritzelt hat. \"Nicht vergessen, den Turm mit dem Leyliniennetz zu verbinden!\"\n\nÄh... keine Ahnung, wie man das bewerkstelligt.\n\nTut mir leid, aber ich hab's nicht so mit der Magie. Wir haben Erzmagier Khadgar und ein paar Kirin Tor nicht weit von hier gesichtet. Im Osten war es, in Richtung der Berge.\n\nVielleicht sollten wir sie um Hilfe bitten?", sourceObjective = "Sprecht mit Erzmagier Khadgar in Talador.", completion = "Ah, Ihr habt also ein Arkanes Sanktum errichtet! Wunderbar!\n\nNur das Verbinden mit dem Leyliniennetz bereitet Euch Schwierigkeiten, nehme ich an?", sourceObjectiveStatus = "unverified-source-field" }
quests[34634] = { id = 34634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tintenherstellung", description = "Wir werden einen Weg finden müssen, einen künstlichen Nexus bei Eurem Turm zu erzeugen.\n\nIch weiß, wo wir das bekommen, was wir brauchen, aber es wird schwer bewacht. Einfach reinstürmen und alles niederballern wird nicht funktionieren.\n\nIch habe einen Plan: eine Schriftrolle der Massenteleportation.\n\nDie Fungusgiganten und Sporenkreaturen da unten sind mit Pusteln übersät, in denen sich eine ölige Substanz befindet. Wenn wir genug von dem Öl haben, könnte ich daraus eine Art Tinte machen, die wir für die Schriftrolle verwenden können.", sourceObjective = "Sammelt 30 pulsierende Pusteln von Sporenseglern und Fungusgiganten in Zangarra.", progress = "Die Giganten haben mehr Pusteln als die Sporensegler, sind aber viel zäher.", completion = "Diese Pusteln zischen förmlich vor Energie. Genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[34635] = { id = 34635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schriftrolle rollen", description = "Damit der Plan aufgeht, brauchen wir arkanes Pergament.\n\nDie latente an diesem Nexus vorherrschende arkane Energie hat die Urtume sofort erstarren lassen und sich in ihren Rinden festgesetzt.\n\nEin paar wurden noch nicht von den Funguskreaturen zerstört. Reißt ein paar Streifen ab, dann kann daraus ein Pergament formen.", sourceObjective = "Reißt 3 Stück Rinde von schlummernden Urtumen in Zangarra ab.", completion = "Was für sauber abgetrennte Stücke! Spitzenmäßig!", sourceObjectiveStatus = "unverified-source-field" }
quests[34636] = { id = 34636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken fangen", description = "Wir müssen uns ein wenig arkane Energie besorgen, um unsere Schriftrolle fertigzustellen. Sie braucht dieses feurige bisschen Extra.\n\nIch habe ein Gerät, mit dem man da unten Energie einfangen kann, also sollten wir keine Zeit verlieren. Die durchdrungenen Kreaturen sollten für uns zwei kein Problem darstellen.", sourceObjective = "Sammelt 3 Arkanvortexe in Zangarra.", completion = "Sehr gut! Das ist genau das, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34639] = { id = 34639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aruunas Verheerung" }
quests[34641] = { id = 34641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Waterlogged Journal" }
quests[34642] = { id = 34642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Lucky Coin" }
quests[34645] = { id = 34645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Warmaster Blugthol" }
quests[34646] = { id = 34646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qiana Mondschatten", description = "Wenn wir diesen Krieg gewinnen wollen, brauchen wir mehr als nur Fußsoldaten. Wir brauchen Champions.\n\nQiana Mondschattens Leistungen in Tanaan und im Abendruhhafen waren ziemlich beeindruckend.\n\nVielleicht solltet Ihr mit ihr darüber sprechen, wie sie eine größere Rolle im Kampf gegen die Eiserne Horde spielen könnte.", sourceObjective = "Sprecht mit Qiana Mondschatten.", completion = "Luuka ist leicht erschüttert, aber er ist in Sicherheit, und nur das zählt.\n\nKommandant, ich verdanke Euch mein Leben. Wir alle tun das.\n\nEs wäre mir eine Ehre, hier in Draenor als Eure Agentin zu dienen. Falls Ihr meine Dienste benötigt, müsst Ihr es nur sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34647] = { id = 34647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Snow-Covered Strongbox" }
quests[34648] = { id = 34648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Gnawed Bone" }
quests[34649] = { id = 34649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Smoldering True Iron Deposit" }
