quests[34652] = { id = 34652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Savage Clam" }
quests[34653] = { id = 34653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus der Arakkoa", description = "Ich nehme an, Ihr kennt die Arakkoa, Kommandant? Ein Volk mächtiger fliegender Vogelmenschen. Extrem feindselig gegenüber Eindringlingen.\n\nBei manchen von ihnen sind die Flügel verkümmert, möglicherweise aufgrund einer Krankheit. Sie werden anscheinend aus der Gesellschaft der Arakkoa ausgestoßen. Man sieht sie hin und wieder in vergessenen Ruinen hausen oder an den Straßen billigen Schmuck verkaufen.\n\nEs sieht so aus, als hätte die Eiserne Horde die Arakkoa durch ihr Eindringen in ihr Gebiet aufgescheucht. Die Ausgestoßenen fliehen in Scharen.\n\nWir sollten mit ihnen Kontakt aufnehmen. Möglicherweise haben sie wertvolle Informationen.", sourceObjective = "Sprecht mit Azik in den Spitzen von Arak.", completion = "<Der Arakkoahändler mustert Euch von oben bis unten.>\n\nWir sind ganz gut ausgerüstet, was? Azik könnte wetten, dass Ihr jemand Wichtiges seid bei Eurem Volk.\n\nAber kommt doch näher, unterhaltet Euch einen Augenblick mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[34654] = { id = 34654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag: Dagg Found at Daggermaw Ravine" }
quests[34655] = { id = 34655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatten von Skettis", description = "Mein Volk flüchtete scharenweise aus unserer Heimat. Ich verkaufe Glücksbringer, um die Reise einfacher zu machen.\n\nDoch wie ich sehe, seid Ihr nicht an Glückbringern interessiert... Nein, Ihr sucht nach Antworten.\n\nSkettis liegt direkt da vorne. Einst war es eine große Stadt, die Terokk als Zufluchtsort für die Unerwünschten errichtete. Doch jetzt ist es ein ruiniertes Elendsviertel.\n\nEin alter Geschichtenerzähler lebt dort – ein Schriftenbewahrer namens Reshad. Findet ihn und sagt ihm diese Worte: \"Der Schatten wächst.\" Er weiß dann, dass Ihr <ein Freund/eine Freundin> seid.\n\nGeht jetzt. Eure Gegenwart ist schlecht fürs Geschäft.", sourceObjective = "Sprecht mit Reshad in Skettis.", progress = "Wenn Ihr wegen eines legendären Folianten von unvorstellbarer Macht hier seid, muss ich Euch leider enttäuschen. Ich bin nur ein Hüter der Geschichte.\n\nAußerdem bin ich im Augenblick gerade sehr beschäftigt.", completion = "Azik muss etwas in Euch gesehen haben. Ich vertraue seinem Urteil, denn n-\n\n<Reshad wird unterbrochen, als ein warmer Windhauch durch die Hütte fegt.>\n\nOh je... Sie sind hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[34656] = { id = 34656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor aller Augen verborgen", description = "<Reshad fängt an, sich hastig Schriftrollen in seine Robe zu stopfen.>\n\nIch dachte, ich hätte mehr Zeit, um mich vorzubereiten! In Skettis sind mächtige Relikte versteckt. Wenn ich ohne sie fortgehe, könnte ich auch gleich hier sterben.\n\nZum einen handelt es sich um ein Paar Flügelklingen, die von einer Statue in der Nähe des Vordereingangs gehalten wird. Ihr seid vermutlich auf Eurem Weg hinein daran vorbeigekommen.\n\nEine weitere Statue auf der östlichen Seite der Ruinen trägt eine weiße Maske.\n\nBringt mir diese Artefakte, und ihre Geheimnisse sollen Euer sein!", sourceObjective = "Bergt die verwitterten Flügelklingen und die zerlumpte Maske.", progress = "Flügelklingen, im Namen einer Sonnengöttin geschmiedet, um ihren Kindern Freiheit und Ruhm zu verschaffen.\n\nEine Maske, einst getragen von einem mächtigen König, der damit unerkannt unter seinem Volk wandelte, um die wahre Natur seiner Untertanen zu erkennen.", completion = "Wer hätte gedacht, dass man diese Schätze eines Tages an Strohpuppen finden würde, schutzlos der Sonne ausgesetzt? Für jeden sichtbar sind solche Schätze mitunter am besten verborgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34657] = { id = 34657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jünger des Sonnengottes", description = "Die Arakkoa aus Himmelsnadel stehen unter der Herrschaft der Jünger von Rukhmar. Sie schmähen diejenigen unter uns, die den Fluch des Sethe tragen, und haben angeordnet, dass wir im Namen ihrer Sonnengöttin ausgelöscht werden sollen.\n\nBald wird sich ihr Blick auf die Länder jenseits von Arak richten.\n\nFordert ihre Krieger heraus. Verschafft mir Zeit, damit ich meine Flucht vorbereiten kann, und helft mir, ihren Niedergang in die Wege zu leiten.", sourceObjective = "Tötet 8 Klingenschwingen der Jünger.", completion = "Azik tat gut daran, Euch an mich zu verweisen. Falls Ihr hergekommen seid, um Skettis zu helfen, so hätten wir uns treffen müssen.\n\nFalls Ihr hergekommen seid, um uns anzugreifen, dann wäre ich ohnehin längst tot, nicht wahr?\n\n<Reshad stößt ein krächzendes Lachen aus und verstaut eine weitere Schriftrolle unter seinen Gewändern.>\n\nSo, das wäre schon fast alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[34658] = { id = 34658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von ganz oben", description = "Die Jünger von Rukhmar sind die herrschende Klasse an den Spitzen. Ihr Einfluss ist absolut, ihre Kundgebungen werden als Wille von Rukhmar persönlich ausgelegt.\n\nDer für die Reinigung verantwortliche Herold folgt ganz gewiss solch einem Befehl; einer Liste mit Namen und Orten, deren Auslöschung sie planen.\n\nDiese Liste wäre in den kommenden Tagen von unschätzbarem Wert. Besorgt sie für mich und bringt diesen Herold zum Schweigen!", sourceObjective = "Erbeutet die Proklamation der Jünger vom Sonnenweisen Rathyx.", progress = "<Reshad zurrt noch eine Rolle an Percy fest, der schwach mit einem heiseren Krächzen protestiert.>\n\nOh, hört schon auf zu quengeln.", completion = "Ah ja, mein Name ist ganz oben auf der Liste. Und einige Krallenpriester aus der Schattenlichtung stehen auch drauf.\n\nSie fürchten Terokks Rückkehr. Das sollten sie auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[34659] = { id = 34659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Greisin", sourceObjective = "Stellt Euch mit der Losung bei Ornekka im Krähenwinkel vor.", completion = "Ich werde Euch die richtige Richtung weisen, doch kann ich nicht garantieren, dass Ihr die Reise überlebt.\n\nKrah-hah haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[34660] = { id = 34660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorkras Sturz" }
quests[34662] = { id = 34662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring der Prüfung: Malmhammer", description = "Ihr wollt also im Ring der Prüfung kämpfen, was? Na, wenn Ihr unbedingt sterben wollt, <Kleiner/Kleines>!\n\nEuer erster Kampf geht gegen einen außergewöhnlich großen und wütenden Oger mit Namen Malmhammer. Das ist aber noch nicht alles. Ihr müsst außerdem seinen Gefährten, den gepanzerten Eber, ausschalten. Malmhammer steigt nie ohne ihn in den Ring!\n\nIch hoffe, Ihr habt Eure Angelegenheiten in Ordnung gebracht, da der letzte Gladiator, der gegen Malmhammer gekämpft hat, in einem Leichensack nach Hause gekommen ist...\n\nIch zähle auf Euch! Schafft Euren Hintern in die Arena und sprecht mit meinem Mitarbeiter Wodin, wenn Ihr den Kampf wollt!", sourceObjective = "Besiegt Malmhammer im Ring der Prüfung.", completion = "Boah! Ich hätte nicht sagen können, ob Eberhard da drin gequiekt hat oder ob Ihr Malmhammer dazu gebracht habt, wie ein kleines Baby zu schreien!\n\nIhr habt Talent, Kleiner!\n\nHier ist Euer Anteil am Gewinn, aber warum jetzt aufhören? Zusammen können wir bergeweise Gold verdienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34663] = { id = 34663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring der Prüfung: Reißklaue", description = "Ihr mögt Malmhammer besiegt haben, aber jetzt ist Schluss mit lustig... Noch habt Ihr nicht gewonnen!!\n\nDie Hochfelsoger nehmen Gladiatorenkämpfe ernst. Als sie also den Ring der Prüfung gebaut haben, suchten sie weit und breit nach den brutalsten Kreaturen, die sie finden konnten!\n\nIhr kämpft gegen einen Schreckensraben, den die Oger Reißklaue nennen! Ich sage Euch, {name}, irgendetwas stimmt mit diesem Vogel nicht... Ich glaube, Töten bereitet ihm wirklich Freude!\n\nReißklaue hat mit dem letzten Gladiator stundenlang gespielt, bevor er ihn gefressen hat.\n\nVersucht, am Leben zu bleiben!", sourceObjective = "Besiegt Reißklaue im Ring der Prüfung.", completion = "Ihr habt es geschafft, {name}! Ihr habt Reißklaue tatsächlich besiegt!\n\nIch hätte es niemals geglaubt, wenn ich es nicht mit eigenen Augen gesehen hätte. Ihr habt Feuer im Bauch und Gold im Blick, Kleiner!\n\nHier ist Euer Anteil am Gewinn, aber hört jetzt nicht auf! Ihr habt eine Glückssträhne!", sourceObjectiveStatus = "unverified-source-field" }
quests[34664] = { id = 34664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring der Prüfung: Hol'yelaa", description = "Ihr habt die ersten beiden Kämpfe gewonnen, aber von jetzt an wird es immer schwieriger!\n\nAls Nächstes kämpft Ihr gegen den absolut verrückten Hol'yelaa, einen früheren Rangari.\n\nNein, im Ernst... Hol'yelaa ist vollkommen durchgeknallt!\n\nVor Jahren hat er einmal auf einer Spähermission ganz allein seine gesamte Rangarieinheit vor einem Rudel Garn bewahrt. Dabei ist in ihm drin etwas durchgebrannt...\n\nEs dauerte nicht mehr lange, bis Hol'yelaa auch noch den letzten Funken Verstand verlor und sich gegen seine eigene Einheit wandte!\n\nAlso schön, genug der aufmunternden Worte! Geht dort rein und zeigt ihm, was 'ne Harke ist!", sourceObjective = "Besiegt Hol'yelaa im Ring der Prüfung.", completion = "Euch in der Arena kämpfen zu sehen, ist wie einen Künstler bei der Vollendung seines Meisterwerks zu beobachten!\n\nNun, ein Meisterwerk aus Blut und zerschmetterten Knochen... aber hey: Jeder muss irgendein Talent haben, oder?\n\nHier ist Euer Anteil am Gewinn! Dieser Kampf war so gut, dass ich tatsächlich darüber nachgedacht habe, Euch einen Bonus zu geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[34665] = { id = 34665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring der Prüfung: Hauptmann Funkenschlag", description = "Ihr habt Euch in der Arena einen Namen gemacht, {name}!\n\nAber freut Euch nicht zu sehr... Ruhm hat seine Konsequenzen! Ihr wurdet von einem aufstrebenden Gladiator herausgefordert, der sich selbst einen Namen machen möchte. Kommt Euch das bekannt vor?\n\nEuer nächster Kampf geht gegen Hauptmann Funkenschlag, gegen einen Söldner, der hierhergekommen ist, um für die Eiserne Horde zu kämpfen.\n\nDie Eiserne Horde wirft nicht gerade mit Gold um sich, also ist er jetzt hier!\n\nEr hat einen Schredder, also passt auf die Klingen auf... und auf das Feuer... besonders auf das Feuer!", sourceObjective = "Besiegt Hauptmann Funkenschlag im Ring der Prüfung.", completion = "Ich habe noch nie jemanden gesehen, der einen Schredder derart auseinandergenommen hat!\n\nIhr habt mir eine Menge Geld eingebracht, {name}! Nur die besten Gladiatoren überleben die Arena so lange. Und doch seid Ihr irgendwie anders...\n\nEs sind Eure Augen... Sie sehen aus, als hätten sie schon eintausend Mal dem Tod ins Gesicht geblickt und nicht ein Mal dabei geblinzelt.\n\nNehmt Euren Anteil am Gewinn und ruht Euch aus. Der größte Kampf liegt immer noch vor Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[34666] = { id = 34666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring der Prüfung: Roakk der Zelot", description = "Die letzte Runde beginnt, {name}! Ihr habt die besten Herausforderer überwunden! Von hier gibt es keinen anderen Weg als direkt bis an die Spitze... zum amtierenden Champion des Rings der Prüfung!\n\nDer aktuelle Champion ist ein Arakkoa mit Namen Roakk der Zelot. Roakk ist ein Verrückter! Er sagt, er wäre auf irgendeinem göttlichen Kreuzzug für die Sonne oder so etwas.\n\nVerrückt oder nicht, er ist einer der gefährlichsten Kämpfer, die ich je gesehen habe, und hat sogar schon im Kolosseum von Hochfels gekämpft!\n\nIch werde Euch nicht belügen, Ihr werdet da drin wahrscheinlich sterben... Viel Glück!", sourceObjective = "Besiegt Roakk im Ring der Prüfung.", completion = "Lang lebe der Champion! Ich wusste, Ihr könnt es schaffen!\n\nKonntet Ihr das Brüllen der Menge hören? Die Arena hat gebebt wie von einem Donner!\n\nDas ist nur der Anfang! Das Kolosseum von Hochfels wartet auf Euch. Als Champion des Rings der Prüfung wird von Euch erwartet, dass Ihr dort erscheint!", sourceObjectiveStatus = "unverified-source-field" }
quests[34667] = { id = 34667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hof der Seelen" }
quests[34668] = { id = 34668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Talonpriest Zorkra" }
quests[34671] = { id = 34671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shirzir" }
quests[34672] = { id = 34672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg von Aku'mai", description = "Wir sind dem Opferaltar des Schattenhammers nur knapp entkommen, aber es gibt tiefer in diesen Höhlen noch andere, die Hilfe brauchen. Wenn diese Kultisten ihr Blutritual vollenden, lassen sie Aku'mai den Verschlinger auf die Welt los. Das dürft Ihr nicht zulassen.", sourceObjective = "Tötet Aku'mai den Verschlinger.", completion = "Das war unglaublich, {name}! Die Alten Götter werden es sich jetzt zweimal überlegen, bis sie sich wieder aus ihrem Loch trauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34673] = { id = 34673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg von Aku'mai", description = "Wir wär'n dem Opferaltar des Schattenhammers fast nich' entkommen, aber die ander'n tiefer in der Höhle brauch'n Hilfe. Wenn die das Blutritual beend'n, lass'n die Aku'mai den Verschlinger auf die Welt los. Lasst das nich' zu, Mann.", sourceObjective = "Tötet Aku'mai den Verschlinger.", progress = "Bewegung, {name}! Aku'mai will die Welt verschlingen!", completion = "Das war irrsinnig, {name}! Die Alt'n Götter werden es sich jetzt zweimal überleg'n, bevor sie Euch ans Leder geh'n, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[34674] = { id = 34674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht nach Nagrand tragen", description = "**Streng vertraulich – Kommandant {name}**\n\nNach dem Verlust der Rangaristation in Telaar hat uns Verteidigerin Yrel angewiesen, einen neuen Außenposten in Nagrand zu errichten.\n\nIch habe mir die Freiheit genommen, einige unserer Männer und Vorräte dafür zur Verfügung zu stellen. Rangari D'kaan hat uns bereits benachrichtigt, dass der neue Außenposten bald fertiggestellt wird. Er lässt Euch mitteilen, dass alles für Euch bereit steht.\n\nEs wartet ein Greif auf Euch, mit dem Ihr die aktuelle Karawanenlieferung einholen könnt.\n\n– Bodrick Grau, SI:7", sourceObjective = "Sprecht mit Leutnant Balfor bei der Karawane in Nagrand.", completion = "Sie kamen... aus dem... Nichts.\n\n<Der Leutnant wird fast ohnmächtig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34675] = { id = 34675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Kriegshymnenklans", description = "<Der Offizier hat große Schmerzen. Sicher wird er diese Welt bald verlassen.>\n\nDer Kriegshymnenklan. Überraschungsangriff.\n\nRichtung... Westen.\n\n<Er hält kurz inne, bevor er fortfährt.>\n\nSie haben die... Pläne...\n\n<Das waren seine letzten Worte.>", sourceObjective = "Sprecht mit Rangari D'kaan in der Telaaristation.", completion = "Kommandant. Gut, dass Ihr hier seid, wir haben viel zu besprechen.\n\nDie Situation in Nagrand verschlechtert sich immer schneller. Wir haben Telaar verloren.\n\nUm es noch schlimmer zu machen, hat Grommash Garrosh Höllschrei als neuen Kriegsherrn des Kriegshymnenklans ausgerufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34676] = { id = 34676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entscheidende Weg", description = "Die herbstlichen Wälder Taladors befinden sich an einem Scheideweg, der für diesen Kontinent unglaublich wichtig ist, Kommandant. Vor der Westküste ist die Flotte der Eisernen Horde bereits auf dem Weg von Gorgrond nach Shattrath.\n\nTalador wird fallen, wenn wir sie nicht verstärken. Ich habe mir die Freiheit herausgenommen, Vorarbeiter Eksos loszuschicken. Er hat bereits begonnen, in der Nähe der Landungsstelle der Eisernen Horde einen Außenposten für unsere Streitkräfte zu errichten. Er erwartet weitere Befehle.", sourceObjective = "Sprecht mit Dungar Trinkfest, um Euren Flug nach Talador anzutreten.", completion = "Ich werde Eure Zeit nicht verschwenden, Kommandant. Reden wir über unsere Strategie.", sourceObjectiveStatus = "unverified-source-field" }
quests[34678] = { id = 34678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzbereit", description = "Der Kriegshymnenklan hat uns hart getroffen. Wir haben Telaar verloren, doch jetzt haben wir eine seltene Gelegenheit, den Kriegshymnenklan mitten ins Herz zu treffen.\n\nWir brauchen Eure Führungsqualitäten und Eure Weisheit, um das hier durchzuziehen, {name}.\n\nZuerst jedoch gilt es, unsere Überlebenden aus Telaar zu befreien. Meine Rangari sind bereit zum Angriff. Wir müssen Euch nur noch zu ihnen bringen.\n\nThaelin hat einen Kopter, mit dem Ihr zu Ihnen gelangen könntet. Doch leider hat er alle Hände voll damit zu tun, dieses höllische Ding instandzuhalten.\n\nKönntet Ihr ihm helfen, es einsatzbereit zu machen?", sourceObjective = "Sammelt die verschiedenen technischen Teile, den Stützrotor und das Übertragungsschwungrad.", progress = "{name}, ich kann gar nicht in Worte fassen, wie erfreut ich bin, Euch zu sehen.", completion = "Für mich? Das wäre doch nicht nötig gewesen.\n\nNun gut, das sollte reichen.\n\nHoffe ich zumindest.", sourceObjectiveStatus = "unverified-source-field" }
quests[34679] = { id = 34679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzställe Verfolgungsereignis" }
quests[34680] = { id = 34680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzwerkstatt Verfolgungsereignis" }
quests[34681] = { id = 34681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sache der Strategie", description = "Die Eiserne Horde ist ein würdiger Feind.\n\nSie haben ihre Flotte von Gorgrond nach Talador verlegt und meine Spione haben davon nix mitbekommen. Talador ist ein wichtiger Knotenpunkt für den ganzen Kontinent. Wir dürf'n ihnen den nicht überlassen.\n\nKeine Sorge, <Scheff/Scheffin>, wir kümmern uns drum. Vorarbeiter Grobash baut gerade jetzt einen Außenposten für unsere Truppen. Der wird bereit sein, sobald Ihr dort ankommt, Kommandant.", sourceObjective = "Sprecht mit Bron Himmelshorn, um Euren Flug nach Talador anzutreten.", completion = "Wie Ihr befehlt. Ich benötige Euren Rat, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[34682] = { id = 34682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Überraschungsparty", description = "Nicht viele haben den Angriff des Kriegshymnenklans überlebt. Die wenigen Rangari, die übrig sind, sind zu einem der Felsen über Telaar hinaufgestiegen.\n\nDie Rangari erwarten Euch. Sie planen einen Überraschungsangriff zur Vergeltung.\n\nDer Autopilot von meinem Gyrokopter ist so eingestellt, dass er Euch nach dort oben bringt. Der Gyrokopter hat ein wenig abbekommen, aber ich glaube, einen letzten Ausflug wird er noch überstehen.\n\nVielleicht.", sourceObjective = "Benutzt Thaelins Gyrokopter, um zum Hochstand der Rangari zu gelangen.", completion = "Wir haben Euch erwartet, Kommandant.\n\nDie Lage ist ernst, aber mit Eurer Hilfe zu bewältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34683] = { id = 34683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schritt voraus", description = "Boss, Durotan is' mit Draka un' Gazlowe aufgebrochen, um die Truppenbewegungen der Eisernen Horde entlang der Küste zu verfolgen.\n\nSie wart'n auf Euch auf den Klipp'n im Nordwesten.", sourceObjective = "Sprecht mit Durotan in Talador.", completion = "Ah, {name}. Ich habe Euren Geruch erkannt. Wir haben auf Eure Ankunft gewartet, bevor wir mit unserer Aufgabe beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34685] = { id = 34685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsteigender Rauch", description = "Aruuna brennt.\n\nDie Arakkoa sind von ihren Türmen zu uns hinuntergeflogen und verbrennen jetzt alles zu Asche. Die Draenei, die Talbuks, ja selbst die Orcs: Bündnisse bedeuten ihnen nichts. Sie wollen nur sehen, wie die Welt brennt.\n\nIch bin nur knapp entkommen, doch mein bester Freund Barum blieb zurück, um seine Tochter zu suchen. Alle anderen sagen, dass Ihr <ein großer Held/eine große Heldin seid>. Ich flehe Euch an, geht nach Aruuna und findet die beiden.", sourceObjective = "Findet Kristallformer Barum in der Nähe von Aruuna in Talador.", completion = "Kalaam hat Euch geschickt? Beim Licht, ich wusste, dass ich mich auf ihn verlassen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[34691] = { id = 34691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur der Anfang", description = "Ich vergebe Orgrim. Er handelte so, wie wir alle handeln müssen – wir tun, was uns unser Herz sagt.\n\nWir sollten zu Eurem Außenposten zurückkehren und unsere nächsten Schritte planen. Es gibt hier nichts, was wir noch tun können.\n\nIch werde den Menschen bitten, ein Portal für uns zu öffnen. Wir werden uns dort erneut unterhalten.", sourceObjective = "Sprecht mit Durotan in Talador.", sourceObjectiveStatus = "unverified-source-field" }
quests[34692] = { id = 34692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegieren auf Draenor", description = "Auf Draenor gibt es mehr Arbeit, als wir selbst erledigen können. Wir müssen damit anfangen, sie zu delegieren.\n\nEine Gruppe von Nachtelfen benötigt beim Außenposten Sternenfall Unterstützung.\n\nQiana ist wie gemacht für diese Mission.", sourceObjective = "Schickt Qiana Mondschatten über den Befehlstisch auf eine Mission.", progress = "Ihr könnt den Befehlstisch verwenden, um Euren Anhängern Missionen zuzuweisen.", completion = "Das ist ein guter Anfang, doch wir werden mehr Champions brauchen, um mit den vor uns liegenden Prüfungen fertig zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34696] = { id = 34696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lady des Lichts", description = "{name}, ja? Ihr habt hier das Sagen? Ich bin Ritterfürst Dranarus, zu Euren Diensten.\n\nLady Liadrin geht in der Nähe von Auchindoun, südwestlich von hier, der mutmaßlichen Anwesenheit von Dämonen auf den Grund. Sie will verhindern, dass Auchindoun in Gul'dans Hände fällt, und hat ausdrücklich um Eure Hilfe gebeten.\n\nWenn Ihr aufbrechen würdet, sobald es Euch genehm ist, wäre die Lady sehr dankbar, da bin ich mir sicher.", sourceObjective = "Sprecht mit Lady Liadrin an der Brennenden Front in Talador.", completion = "Wir können später noch plaudern. Es gibt dringendere Probleme!", sourceObjectiveStatus = "unverified-source-field" }
quests[34697] = { id = 34697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wiederentdeckte Legende", description = "Wenn Eure Truppen das Kämpfen lernen sollen, bringt Ihr es ihnen besser bei! Und zwar richtig.\n\nHabt Ihr jemals von Kash'drakor gehört?\n\nEr ist ein berühmter Frostwolfkrieger, der einst versuchte uns Schädel zu bezwingen. Er hätte auch gewonnen, wenn die Oger ihn nicht gefangen genommen hätten.\n\nIm Norden befindet sich die Steinbrecherarena. Dort haben sie ihn und einige weitere große, böse Gladiatoren hingebracht.\n\nWenn Ihr einen Weg findet, sie zu befreien, könnten sie die besten Ausbilder sein, die Ihr Euch nur wünschen könntet.", sourceObjective = "Findet Kash'drakor bei der Steinbrecherarena in Gorgrond.", completion = "Der Lachende Schädel hat Euch geschickt? Wäre es irgendein anderer Klan, hätte ich laut darüber gelacht.\n\nIch bin Kash'drakor, Held des Frostwolfklans und Champion der Steinbrecher-Sklavenarena.\n\nDoch trotz dieser Titel bin ich auf Eure Hilfe angewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34698] = { id = 34698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklavenjäger", description = "Jedes Mal, wenn ein Gladiator aus den Ruinen der Steinbrecher entkommt, ist einer ihrer harten Sklavenjäger hinter uns her.\n\nIch halte mich für einen fähigen Krieger. Jahre des Überlebens in der Arena haben mich dazu gemacht.\n\nAber diese Sklavenjäger markieren die Sklaven mit magischen Anhängern. Damit können sie uns überall aufspüren, wo wir auch hingehen, und uns töten, wenn wir schlafen oder gerade nicht wachsam genug sind.\n\nIch habe kein Recht, Euch darum zu bitten, aber könntet Ihr die Ruinen der Steinbrecher betreten und diese Anhänger besorgen?", sourceObjective = "Besorgt die Anhänger von Brol, Krag und Mol.", progress = "Habt Ihr die Anhänger?", completion = "Mit dieser einen Tat habt Ihr mehr Ehre bewiesen, als ich seit vielen Jahren gesehen habe.\n\nWenn das hier vorbei ist, werde ich mich mit meiner Axt bei Euren Streitkräften einreihen und mein Wissen an Eure Truppen weitergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34699] = { id = 34699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gladiatoren auftreiben", description = "Als wir aus den Ruinen der Steinbrecher geflohen sind, mussten wir andere zurücklassen.\n\nWenn wir versuchen, sie zu befreien, und dabei erkannt werden, wissen die Oger, was wir vorhaben. Das Erste, das sie dann tun werden, ist, unsere Freunde zu töten.\n\nEuch kennen die Oger nicht, was Euch die Chance auf einen Kampf eröffnet.\n\nBetretet die Ruinen der Steinbrecher, sucht nach den anderen Gladiatoren und befreit sie aus ihren Ketten. Wenn Ihr das tut, gewinnt Ihr unsere Loyalität.", sourceObjective = "Rettet die Gladiatoren Bruto, Y'kish und Grubenkämpfer Vaandaam.", completion = "Vielen Dank, Fremdling. Jetzt sind wir frei und können Häuptling Kor'gall den Kopf spalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[34700] = { id = 34700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrel", description = "Aus den Ruinen der Steinbrecher zu entkommen, war der einfachere Teil. Der Ogerabschaum, der über die Gruben herrscht, hält noch immer meinen Sohn gefangen.\n\nEine Zeit lang haben sie ihn als Druckmittel gegen mich verwendet, um mich zum Kampf in ihrer Arena zu zwingen. Aber jetzt, da ich entkommen bin, werden sie ihn trainieren, um mich zu ersetzen.\n\nBitte rettet meinen Sohn. Wenn sie mich sehen, werden sie ihn sofort töten.", sourceObjective = "Rettet Nazgrel.", completion = "Eure Tat wird nie vergessen werden, solange ich oder mein Sohn leben. Euch gilt mein Dank und meine Loyalität.", sourceObjectiveStatus = "unverified-source-field" }
quests[34701] = { id = 34701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecher für die Toten", description = "Dem Licht sei Dank, Ihr seid hier! Exarch Maladaar bat mich, Euch zu finden.\n\nWir benötigen Eure Hilfe. Auchindoun wird von Dämonen angegriffen!\n\nGeht so schnell wie möglich zur Brennenden Front im Südwesten! Ihr seid eine der wenigen Personen, denen der Exarch genug vertraut, um ihnen die Verantwortung für die Verteidigung zu übertragen.", sourceObjective = "Sprecht mit Exarch Maladaar an der Brennenden Front in Talador.", completion = "Ich werde nicht zulassen, dass auch nur ein einziger dieser Dämonen Auchindoun betritt. Und Ihr werdet mir dabei helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34702] = { id = 34702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krav'ogra", description = "Steinbrecher hat 'nen Häuptling und 'nen Sklavenmeister. Heute wir beide töten.\n\nZuerst Sklavenmeister Ok'mok. Ich kämpfen in Arena seit ich klein war wie Ihr. Ich kennen Grausamkeit. Sklavenmeister Ok'mok ist Grausamkeit in Person.\n\nIhr wollt 'n wahrer Gladiator sein? Geht zur Steinbrecherarena, läutet den Herausforderungsgong inner Mitte vonner Arena und stellt Euch den Bestien vonne Sklavenmeister.\n\nVielleicht regt Ok'mok sich so auf, dass er selbst runterspringt, um Euch zu töten. Wenn er das macht, macht ihn selber tot.", sourceObjective = "Benutzt den Herausforderungsgong in der Steinbrecherarena, um Sklavenmeister Ok'mok zu töten.", completion = "Ich Euch aus Ferne beobachten. Gute Kampffertigkeiten Ihr habt. Sehr vielversprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[34703] = { id = 34703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt von Kor'gall", description = "Zeit für Rache! Wir werden Kor'gall töten, und Ihr werdet ihm seine Axt entreißen.\n\nZerschmettert diese schwächliche Barriere und folgt der Brücke dahinter, bis Ihr zum Thron des Häuptlings kommt.\n\nIhr habt uns befreit, also gebührt die Ehre des ersten Blutes Euch. Führt den ersten Schlag und wir stürzen uns mit Euch in die Schlacht.", sourceObjective = "Tötet Kor'gall und nehmt Euch seine Axt, Serathil.", progress = "Kor'galls Herrschaft währt schon viel zu lange.", completion = "Für eine Lebenszeit hat die Klinge schon genug Schmerz und Leid verursacht. Wir werden dafür sorgen, dass sie auf angemessene Art beseitigt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[34704] = { id = 34704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wiederentdeckte Legende", description = "Diese Übungsarena ist ein guter Anfang, aber wir werden Trainer brauchen, die uns dabei helfen, unsere Streitkräfte zu würdigen Kämpfern zu formen.\n\nIm Westen wurde eine Draenei gesehen, auf die Akaanis Beschreibung passt.\n\nDas ist interessant, da wir alle sie für tot gehalten haben. Sie war eine der besten Kämpferinnen, die die Draenei jemals aufs Feld geschickt haben. Sie hat nahezu alle Waffen gemeistert, die je geschmiedet oder gefunden wurden.\n\nKommandant, Ihr könntet Euch keinen fähigeren Trainer wünschen. Ich rate Euch, sie aufzusuchen, wenn sie es denn wirklich ist...", sourceObjective = "Findet Gladiatorin Akaani bei der Steinbrecherarena in Gorgrond.", completion = "Ihr seht nicht aus wie ein Kopfgeldjäger der Steinbrecher.\n\nWir konnten aus ihrer tödlichen Arena fliehen, doch nur zu einem hohen Preis. Wir mussten zu viele Freunde zurücklassen und haben zu wenigen Ogern das Licht ausgeblasen.\n\nJemand, den die Oger noch nicht kennen, könnte uns vielleicht weiterhelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34705] = { id = 34705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Shadowmoon Intro" }
quests[34706] = { id = 34706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenkunft", description = "Eure Arbeit hier ist getan, {name}. Ich werde vorerst hier bleiben und helfen, die übrigen Dämonen aus dem Weg zu räumen.\n\nIhr solltet zu Eurem Außenposten zurückkehren und Dranarus von Eurem Erfolg berichten. Er kann die Nachricht dann nach Azeroth weitertragen.", sourceObjective = "Sprecht mit Ritterfürst Dranarus in Vol'jins Stolz.", completion = "Lady Liadrin hat mit Euch eine wahrhaft weise Wahl getroffen. Ich werde Vol'jin unverzüglich von Eurem Sieg unterrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34707] = { id = 34707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenkunft", description = "Gul'dan und seine Spießgesellen täten gut daran, diesen Tag in Erinnerung zu behalten. Mit uns Auchenai ist nicht zu spaßen.\n\nIhr solltet Verteidigerin Icia in Eurem Außenposten Bericht über unseren Erfolg erstatten. Sie wird den versprengten Flüchtlingen und ihren Familien helfen können.", sourceObjective = "Sprecht mit Verteidigerin Icia in Fort Wrynn.", completion = "Ich werde alle verbleibenden Überlebenden zusammentrommeln, damit wir beginnen können, das, was wir verloren haben, neu aufzubauen.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[34708] = { id = 34708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Jehil the Climber", description = "Goren sind gefährlich, besonders in großer Zahl... und erst recht, wenn wir einen blinden, ausgelaugten Schamanen bei uns haben.\n\nGlücklicherweise leben Goren nicht sehr lange. Unglücklicherweise vermehren sie sich aber schnell und wachsen noch schneller.\n\nWenn wir das hier schaffen wollen, müssen wir ihre Brutmutter finden. Wenn wir sie töten und ihre Eier vernichten, sollte das den Ansturm der Goren bremsen. Überprüft die Löcher in der Nähe des Tors zur Schmiede, ich werde sie solange von Drek'Thars Fährte ablenken." }
quests[34709] = { id = 34709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jedes bisschen zählt", description = "Wir brauchen Euch bei der Jorunmine westlich von hier!\n\nMeine Freundin Ageilaa hat mich losgeschickt, um Hilfe zu holen. Exarch Maladaar hat alle Verteidiger hingeschickt, die er entbehren konnte, doch es reicht nicht!\n\nKönnt Ihr zur Mine kommen und uns helfen? Wir brauchen die Kristalle aus der Mine, um weitere Verteidigungsanlagen wie jene, die Ihr an der Brennenden Front sehen könnt, zu errichten.", sourceObjective = "Sprecht mit Ageilaa bei der Jorunmine in Talador.", completion = "Aeun schickt Euch? Hilfe ist endlich eingetroffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34710] = { id = 34710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jedes bisschen zählt", description = "Manduil Himmelsrufer wurde mit einer heiklen Mission zur Jorunmine geschickt, doch er ist schon seit Stunden überfällig.\n\nVermutlich braucht er Hilfe. Er kann Euch über die Situation informieren, wenn Ihr ihn findet, aber wahrscheinlich ist er tief im Innern der Mine.\n\nIhr solltet Euch bei Ageilaa melden. Sie ist eine hiesige draenische Minenarbeiterin und hat sich bereit erklärt, mit uns zusammenzuarbeiten, wenn wir ihr dabei helfen, die Kontrolle über die Mine zurückzuerlangen.", sourceObjective = "Sprecht mit Ageilaa bei der Jorunmine in Talador.", completion = "Aeun hat Euch geschickt? Hilfe ist endlich eingetroffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34711] = { id = 34711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Grund zum Feiern", description = "Sollen wir zu Eurem Außenposten zurückkehren? Dort lässt es sich besser feiern, und es ist sicherer.\n\nIch teleportiere uns dorthin.", sourceObjective = "Sprecht mit Magistra Serena in Fort Wrynn.", completion = "Mit diesem Kristall können wir endlich Euren Turm mit dem Leyliniennetz verbinden.\n\nIch habe außerdem Euren Plan überarbeitet, damit man ihn auch wirklich lesen kann. Einen weiteren Turm zu errichten sollte Euch nun um einiges leichter fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34712] = { id = 34712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Grund zum Feiern", description = "Ich finde, hier ist nicht gerade der beste Ort für eine Unterhaltung.\n\nSollen wir zu Eurem Außenposten zurückkehren? Dort lässt es sich besser feiern.\n\nIch teleportiere uns dorthin.", sourceObjective = "Sprecht mit Magister Krelas in Vol'jins Stolz.", completion = "Mit dem Kristall können wir endlich Euren Turm mit dem Leyliniennetzwerk verbinden!\n\nAußerdem habe ich den Bauplan überarbeitet, was den Bau eines weiteren Turms in Eurer Garnison stark vereinfachen müsste.", sourceObjectiveStatus = "unverified-source-field" }
quests[34713] = { id = 34713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gronnstalker's Cache" }
quests[34714] = { id = 34714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfire Ridge: (RRP) - Treasure - Pale Leather Cache" }
